    "Ultimate-CHATBOT": [
      {
        "name": "ci.yml",
        "path": ".github/workflows/ci.yml",
        "sha": "af688dbc0ea253a328a6f1047c0a19e5de3c172c",
        "size": 6660,
        "content": "name: CI Monorepo\n\non:\n  push:\n    branches: [\"main\"]\n  pull_request:\n    branches: [\"main\"]\n  workflow_dispatch:\n\njobs:\n  detect-changes:\n    name: Detect changes\n    runs-on: ubuntu-latest\n    outputs:\n      js: ${{ steps.filter.outputs.js }}\n      python: ${{ steps.filter.outputs.python }}\n      schemas: ${{ steps.filter.outputs.schemas }}\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n\n      - name: Determine impacted areas\n        id: filter\n        uses: dorny/paths-filter@v3\n        with:\n          filters: |\n            js:\n              - 'apps/**'\n              - 'packages/sdk-js/**'\n              - 'packages/theme/**'\n              - 'package.json'\n              - 'pnpm-workspace.yaml'\n              - 'tsconfig.base.json'\n            python:\n              - 'apps/orchestrator/rasa/actions/**'\n              - 'packages/sdk-py/**'\n              - 'packages/background-agents/**'\n              - 'services/**'\n              - '**/pyproject.toml'\n            schemas:\n              - 'packages/shared-schemas/**'\n\n  js-quality:\n    name: JS lint & test\n    needs: detect-changes\n    if: ${{ needs['detect-changes'].outputs.js == 'true' || needs['detect-changes'].outputs.schemas == 'true' }}\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n\n      - uses: actions/setup-node@v4\n        with:\n          node-version: \"20\"\n          cache: \"pnpm\"\n\n      - uses: pnpm/action-setup@v4\n        with:\n          version: 9\n\n      - name: Enable corepack\n        run: corepack enable\n\n      - name: Install dependencies\n        run: pnpm install --frozen-lockfile\n\n      - name: Lint\n        run: pnpm lint\n        env:\n          FORCE_COLOR: \"1\"\n\n      - name: Test\n        run: pnpm test\n\n  python-quality:\n    name: Python lint & test\n    needs: detect-changes\n    if: ${{ needs['detect-changes'].outputs.python == 'true' || needs['detect-changes'].outputs.schemas == 'true' }}\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n\n      - uses: actions/setup-python@v5\n        with:\n          python-version: \"3.11\"\n\n      - name: Install Poetry\n        run: pipx install poetry==1.8.3\n\n      - name: Install dependencies (quotation service)\n        run: |\n          cd services/quotation\n          poetry install --no-root\n\n      - name: Lint\n        run: |\n          cd services/quotation\n          poetry run flake8\n\n      - name: Test\n        run: |\n          cd services/quotation\n          poetry run pytest -q\n\n      - name: Install dependencies (rasa actions)\n        run: |\n          cd apps/orchestrator/rasa/actions\n          poetry install --no-root\n\n      - name: Test Rasa actions\n        run: |\n          cd apps/orchestrator/rasa/actions\n          poetry run pytest tests/ -v --cov=actions --cov=app --cov-report=xml\n        continue-on-error: true\n\n      - name: Upload coverage\n        uses: codecov/codecov-action@v4\n        with:\n          files: ./apps/orchestrator/rasa/actions/coverage.xml\n          flags: rasa-actions\n          fail_ci_if_error: false\n\n  schemas-verify:\n    name: Schemas codegen verify\n    needs: detect-changes\n    if: ${{ needs['detect-changes'].outputs.schemas == 'true' }}\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n\n      - uses: actions/setup-node@v4\n        with:\n          node-version: \"20\"\n          cache: \"pnpm\"\n\n      - uses: pnpm/action-setup@v4\n        with:\n          version: 9\n\n      - name: Enable corepack\n        run: corepack enable\n\n      - name: Install pnpm dependencies\n        run: pnpm install --frozen-lockfile\n\n      - uses: actions/setup-python@v5\n        with:\n          python-version: \"3.11\"\n\n      - name: Install Poetry\n        run: pipx install poetry==1.8.3\n\n      - name: Install datamodel-code-generator\n        run: pipx install datamodel-code-generator==0.25.4\n\n      - name: Codegen verify\n        run: ./tools/codegen/verify.sh\n\n  secret-scan:\n    name: Secret scan\n    needs: detect-changes\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n\n      - name: Install gitleaks\n        run: |\n          curl -sSL https://github.com/gitleaks/gitleaks/releases/download/v8.29.0/gitleaks_8.29.0_linux_x64.tar.gz | tar -xz\n          sudo mv gitleaks /usr/local/bin/gitleaks\n          gitleaks version\n\n      - name: Secret scan\n        run: ./tools/scripts/secret_scan.sh\n\n  docker-build:\n    name: Docker build verification\n    needs: detect-changes\n    runs-on: ubuntu-latest\n    if: ${{ always() && (needs['detect-changes'].outputs.js == 'true' || needs['detect-changes'].outputs.python == 'true') }}\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n\n      - name: Set up Docker Buildx\n        uses: docker/setup-buildx-action@v3\n\n      - name: Build quotation service\n        uses: docker/build-push-action@v5\n        with:\n          context: ./services/quotation\n          file: ./services/quotation/Dockerfile\n          push: false\n          tags: quotation:test\n          cache-from: type=gha\n          cache-to: type=gha,mode=max\n\n      - name: Build background-agents\n        uses: docker/build-push-action@v5\n        with:\n          context: ./packages/background-agents\n          file: ./packages/background-agents/Dockerfile\n          push: false\n          tags: background-agents:test\n          cache-from: type=gha\n          cache-to: type=gha,mode=max\n\n      - name: Build dashboard\n        uses: docker/build-push-action@v5\n        with:\n          context: ./apps/dashboard\n          file: ./apps/dashboard/Dockerfile\n          push: false\n          tags: dashboard:test\n          cache-from: type=gha\n          cache-to: type=gha,mode=max\n\n      - name: Build rasa-actions\n        uses: docker/build-push-action@v5\n        with:\n          context: ./apps/orchestrator/rasa/actions\n          file: ./apps/orchestrator/rasa/actions/Dockerfile\n          push: false\n          tags: rasa-actions:test\n          cache-from: type=gha\n          cache-to: type=gha,mode=max\n\n      - name: Build whatsapp-adapter\n        uses: docker/build-push-action@v5\n        with:\n          context: ./apps/orchestrator/integrations/whatsapp\n          file: ./apps/orchestrator/integrations/whatsapp/Dockerfile\n          push: false\n          tags: whatsapp-adapter:test\n          cache-from: type=gha\n          cache-to: type=gha,mode=max\n\n      - name: Validate docker-compose\n        run: |\n          docker compose --profile all config --quiet\n\n"
      }
    ]
  },
