        print("\n✓ Configuración válida")

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Centralized Language Processing Module
Optimized for multilingual support, intent classification, and entity extraction
"""

import re
import json
import hashlib
import datetime
from typing import Dict, List, Any, Optional, Tuple
from dataclasses import dataclass, asdict
from enum import Enum
from collections import defaultdict
import unicodedata


class Language(Enum):
    """Supported languages"""
    SPANISH = "es"
    ENGLISH = "en"
    PORTUGUESE = "pt"
    UNKNOWN = "unknown"


class Intent(Enum):
    """Intent types"""
    SALUDO = "saludo"
    DESPEDIDA = "despedida"
    COTIZACION = "cotizacion"
    INFORMACION = "informacion"
    PREGUNTA = "pregunta"
    PRODUCTO = "producto"
    INSTALACION = "instalacion"
    SERVICIO = "servicio"
    OBJECION = "objecion"
    GENERAL = "general"
    ERROR = "error"


@dataclass
class ProcessedMessage:
    """Result of language processing"""
    original: str
    normalized: str
    language: Language
    intent: Intent
    entities: Dict[str, Any]
    confidence: float
    timestamp: datetime.datetime
    session_id: Optional[str] = None
    context: Optional[Dict[str, Any]] = None


@dataclass
class Entity:
    """Extracted entity"""
    type: str
    value: Any
    confidence: float
    start_pos: int
    end_pos: int


class TextNormalizer:
    """Normalize text for processing"""

    def __init__(self):
        self.abbreviations = {
            'm2': 'metros cuadrados',
            'm²': 'metros cuadrados',
            'ml': 'metros lineales',
            'mm': 'milimetros',
            'cm': 'centimetros',
            'm': 'metros',
            'q': 'que',
            'x': 'por',
            'xq': 'porque',
            'pq': 'porque',
            'tb': 'tambien',
            'tmb': 'tambien',
            'd': 'de',
            'k': 'que',
        }

    def normalize(self, text: str, language: Language = Language.SPANISH) -> str:
        """Normalize text"""
        if not text:
            return ""

        # Convert to lowercase
        text = text.lower()

        # Remove extra whitespace
        text = re.sub(r'\s+', ' ', text)

        # Remove accents (for better matching)
        text = self._remove_accents(text)

        # Expand abbreviations
        text = self._expand_abbreviations(text)

        # Normalize numbers
        text = self._normalize_numbers(text)

        # Remove special characters (keep alphanumeric, spaces, and basic punctuation)
        text = re.sub(r'[^\w\s\.\,\-\+]', ' ', text)

        return text.strip()

    def _remove_accents(self, text: str) -> str:
        """Remove accents from text"""
        nfkd = unicodedata.normalize('NFKD', text)
        return ''.join([c for c in nfkd if not unicodedata.combining(c)])

    def _expand_abbreviations(self, text: str) -> str:
        """Expand common abbreviations"""
        words = text.split()
        expanded = []
        for word in words:
            if word in self.abbreviations:
                expanded.append(self.abbreviations[word])
            else:
                expanded.append(word)
        return ' '.join(expanded)

    def _normalize_numbers(self, text: str) -> str:
        """Normalize number formats"""
        # Convert "10x5" to "10 x 5"
        text = re.sub(r'(\d+)\s*[x×]\s*(\d+)', r'\1 x \2', text)
        # Convert "10m x 5m" to "10 metros x 5 metros"
        text = re.sub(r'(\d+)\s*m\s*[x×]\s*(\d+)\s*m', r'\1 metros x \2 metros', text)
        return text


