Te puedo ayudar con:
🏗️ **Cotizaciones** - Paneles Isodec, Isoroof, chapas, calameria
ℹ️ **Información** - Sobre nuestros productos y servicios
📞 **Contacto** - Para consultas específicas

¿En qué te puedo ayudar hoy?`,
      timestamp: new Date(),
      metadata: { tipo: 'informacion' }
    }])
  }, [])

  // Auto-scroll al final
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  // Enviar mensaje
  const handleSendMessage = async () => {
    if (!inputMessage.trim() || isLoading) return

    const userMessage: Message = {
      id: `user_${Date.now()}`,
      role: 'user',
      content: inputMessage,
      timestamp: new Date()
    }

    setMessages(prev => [...prev, userMessage])
    setInputMessage('')
    setIsLoading(true)

    try {
      // Usar el motor de cotización integrado con base de conocimiento evolutiva
      const response = await fetch('/api/integrated-quote', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'process',
          consulta: inputMessage,
          userPhone,
          userName: 'Cliente'
        })
      })

      const data = await response.json()

      if (data.success && data.data?.respuesta) {
        const respuesta = data.data.respuesta

        const assistantMessage: Message = {
          id: `assistant_${Date.now()}`,
          role: 'assistant',
          content: respuesta.mensaje,
          timestamp: new Date(),
          metadata: {
            tipo: respuesta.tipo,
            cotizacion: respuesta.cotizacion,
            productos_sugeridos: respuesta.recomendaciones || [],
            preguntas_frecuentes: []
          }
        }

        setMessages(prev => [...prev, assistantMessage])

        // Mostrar información adicional si es cotización
        if (respuesta.tipo === 'cotizacion' && respuesta.cotizacion) {
          const cotizacionMessage: Message = {
            id: `quote_${Date.now()}`,
            role: 'system',
            content: `💰 Cotización generada con confianza: ${(respuesta.confianza * 100).toFixed(1)}%`,
            timestamp: new Date()
          }
          setMessages(prev => [...prev, cotizacionMessage])
        }

        // Mostrar patrones aplicados si hay
        if (respuesta.patrones_aplicados && respuesta.patrones_aplicados.length > 0) {
          const patronesMessage: Message = {
            id: `patterns_${Date.now()}`,
            role: 'system',
            content: `🧠 Patrones aplicados: ${respuesta.patrones_aplicados.join(', ')}`,
            timestamp: new Date()
          }
          setMessages(prev => [...prev, patronesMessage])
        }

        // Mostrar conocimiento utilizado
        if (respuesta.conocimiento_utilizado && respuesta.conocimiento_utilizado.length > 0) {
          const conocimientoMessage: Message = {
            id: `knowledge_${Date.now()}`,
            role: 'system',
            content: `📚 Conocimiento utilizado: ${respuesta.conocimiento_utilizado.join(', ')}`,
            timestamp: new Date()
          }
          setMessages(prev => [...prev, conocimientoMessage])
        }

        // Actualizar tokens de contexto
        setContextTokens(prev => Math.min(maxContextTokens, prev + inputMessage.length / 4))
      } else {
        throw new Error(data.error || 'Error procesando mensaje')
      }
    } catch (error) {
      console.error('Error sending message:', error)

      const errorMessage: Message = {
        id: `error_${Date.now()}`,
        role: 'assistant',
        content: 'Lo siento, hubo un problema procesando tu mensaje. Por favor, intenta de nuevo.',
        timestamp: new Date(),
        metadata: { tipo: 'error' }
      }

      setMessages(prev => [...prev, errorMessage])
    } finally {
      setIsLoading(false)
    }
  }

  // Comprimir contexto
  const handleCompressContext = async () => {
    try {
      const response = await fetch('/api/context', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'compress_context',
          session_id: sessionId
        })
      })

      if (response.ok) {
        setContextTokens(prev => Math.max(0, prev - 2000))

        const systemMessage: Message = {
          id: `system_compress_${Date.now()}`,
          role: 'system',
          content: 'Contexto comprimido automáticamente para optimizar el rendimiento.',
          timestamp: new Date()
        }

        setMessages(prev => [...prev, systemMessage])
      }
    } catch (error) {
      console.error('Error compressing context:', error)
    }
  }

  // Nuevo chat
  const handleNewChat = () => {
    const newSessionId = `bmc_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`
    setSessionId(newSessionId)
    setMessages([{
      id: 'welcome',
      role: 'assistant',
      content: `¡Hola! 👋 Soy el asistente de BMC Construcciones.

Te puedo ayudar con:
🏗️ **Cotizaciones** - Paneles Isodec, Isoroof, chapas, calameria
ℹ️ **Información** - Sobre nuestros productos y servicios
📞 **Contacto** - Para consultas específicas

¿En qué te puedo ayudar hoy?`,
      timestamp: new Date(),
      metadata: { tipo: 'informacion' }
    }])
    setContextTokens(0)
  }

  // Renderizar mensaje
  const renderMessage = (message: Message) => {
    const isUser = message.role === 'user'
    const isSystem = message.role === 'system'

    return (
      <div key={message.id} className={`flex ${isUser ? 'justify-end' : 'justify-start'} mb-4`}>
        <div className={`max-w-[80%] ${isUser ? 'order-2' : 'order-1'}`}>
          <div className={`p-4 rounded-lg ${
            isUser 
              ? 'bg-primary text-primary-foreground' 
              : isSystem
                ? 'bg-secondary text-secondary-foreground text-sm italic'
                : 'bg-muted'
          }`}>
            <div className="flex items-center gap-2 mb-2">
              <span className="font-semibold capitalize">
                {isUser ? 'Tú' : isSystem ? 'Sistema' : 'Asistente BMC'}
              </span>
              {message.metadata?.tipo && (
                <Badge variant="outline" className="text-xs">
                  {message.metadata.tipo}
                </Badge>
              )}
            </div>

            <div className="whitespace-pre-wrap">{message.content}</div>

            {/* Mostrar cotización si existe */}
            {message.metadata?.cotizacion && (
              <div className="mt-4 p-3 bg-green-50 dark:bg-green-900/20 rounded-lg border">
                <div className="flex items-center gap-2 mb-2">
                  <Calculator className="w-4 h-4 text-green-600" />
                  <span className="font-semibold text-green-800 dark:text-green-200">
                    Cotización Generada
                  </span>
                </div>
                <div className="text-sm space-y-1">
                  <div><strong>Producto:</strong> {message.metadata.cotizacion.producto}</div>
                  <div><strong>Descripción:</strong> {message.metadata.cotizacion.descripcion}</div>
                  <div><strong>Precio Base:</strong> ${message.metadata.cotizacion.precio_base?.toLocaleString()}</div>
                  <div><strong>Total:</strong> ${message.metadata.cotizacion.total?.toLocaleString()}</div>
                  <div><strong>Código:</strong> {message.metadata.cotizacion.codigo}</div>
                </div>
              </div>
            )}

            {/* Mostrar productos sugeridos */}
            {message.metadata?.productos_sugeridos && message.metadata.productos_sugeridos.length > 0 && (
              <div className="mt-4 space-y-2">
                <div className="flex items-center gap-2">
                  <Building2 className="w-4 h-4 text-blue-600" />
                  <span className="font-semibold text-blue-800 dark:text-blue-200">
                    Productos Sugeridos
                  </span>
                </div>
                {message.metadata.productos_sugeridos.map((producto: any, index: number) => (
                  <div key={index} className="p-2 bg-blue-50 dark:bg-blue-900/20 rounded text-sm">
                    <div className="font-medium">{producto.nombre}</div>
                    <div className="text-gray-600 dark:text-gray-400">{producto.descripcion}</div>
                    <div className="text-green-600 font-medium">
                      ${producto.precio_estimado}/m²
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* Mostrar preguntas frecuentes */}
            {message.metadata?.preguntas_frecuentes && message.metadata.preguntas_frecuentes.length > 0 && (
              <div className="mt-4 space-y-2">
                <div className="flex items-center gap-2">
                  <Info className="w-4 h-4 text-purple-600" />
                  <span className="font-semibold text-purple-800 dark:text-purple-200">
                    Preguntas Relacionadas
                  </span>
                </div>
                {message.metadata.preguntas_frecuentes.map((faq: any, index: number) => (
                  <div key={index} className="p-2 bg-purple-50 dark:bg-purple-900/20 rounded text-sm">
                    <div className="font-medium">{faq.pregunta}</div>
                    <div className="text-gray-600 dark:text-gray-400">{faq.respuesta}</div>
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="text-xs text-gray-500 mt-1">
            {message.timestamp.toLocaleTimeString()}
          </div>
        </div>
      </div>
    )
  }

  const contextProgress = (contextTokens / maxContextTokens) * 100

  return (
    <Card className={`h-[calc(100vh-120px)] flex flex-col ${className}`}>
      <CardHeader className="flex flex-row items-center justify-between pb-2">
        <CardTitle className="text-lg font-semibold flex items-center">
          <MessageSquare className="w-5 h-5 mr-2" />
          Chat BMC - {userPhone}
        </CardTitle>
        <div className="flex items-center space-x-2">
          <Button 
            variant="outline" 
            size="sm" 
            onClick={handleCompressContext} 
            disabled={isLoading || contextProgress < 50}
          >
            <RefreshCw className="w-4 h-4 mr-1" /> Comprimir
          </Button>
          <Button 
            variant="outline" 
            size="sm" 
            onClick={handleNewChat} 
            disabled={isLoading}
          >
            <PlusCircle className="w-4 h-4 mr-1" /> Nuevo Chat
          </Button>
        </div>
      </CardHeader>

      <CardContent className="flex-grow flex flex-col p-0">
        <div className="flex-grow p-4 overflow-y-auto">
          <div className="space-y-4">
            {messages.length === 0 && (
              <div className="text-center text-muted-foreground py-8">
                Inicia una conversación para ver el historial.
              </div>
            )}
            {messages.map(renderMessage)}
            {isLoading && (
              <div className="flex justify-start">
                <div className="max-w-[80%] p-4 rounded-lg bg-muted">
                  <div className="font-semibold">Asistente BMC</div>
                  <div className="flex items-center gap-2">
                    <RefreshCw className="w-4 h-4 animate-spin" />
                    <span>Procesando tu consulta...</span>
                  </div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </div>

        <div className="p-4 border-t">
          <div className="flex items-center justify-between text-sm text-muted-foreground mb-2">
            <span>Uso de Contexto: {contextTokens}/{maxContextTokens} tokens</span>
            <Badge variant={contextProgress > 80 ? 'destructive' : contextProgress > 50 ? 'warning' : 'secondary'}>
              {contextProgress.toFixed(1)}%
            </Badge>
          </div>
          <div className="w-full bg-gray-200 rounded-full h-2 mb-4">
            <div 
              className={`h-2 rounded-full transition-all ${
                contextProgress > 80 ? 'bg-red-500' : contextProgress > 50 ? 'bg-yellow-500' : 'bg-green-500'
              }`}
              style={{ width: `${Math.min(100, contextProgress)}%` }}
            />
          </div>

          <form onSubmit={(e) => { e.preventDefault(); handleSendMessage(); }} className="flex space-x-2">
            <Input
              className="flex-grow"
              value={inputMessage}
              placeholder="Escribe tu consulta de cotización..."
              onChange={(e) => setInputMessage(e.target.value)}
              disabled={isLoading}
            />
            <Button type="submit" disabled={isLoading || !inputMessage.trim()}>
              <Send className="w-4 h-4 mr-2" /> Enviar
            </Button>
          </form>
        </div>
      </CardContent>
    </Card>
  )
}

'use client'

import React, { useEffect, useMemo, useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { RefreshCw, Pause, Play, ExternalLink, Store } from 'lucide-react'

interface MercadoLibreListing {
  id: string
  title: string
  price: number
  currency_id: string
  available_quantity: number
  sold_quantity?: number
  status: string
  permalink: string
  date_created?: string
  last_updated?: string
}

const statusColors: Record<string, string> = {
  active: 'bg-emerald-100 text-emerald-800',
  paused: 'bg-yellow-100 text-yellow-800',
  closed: 'bg-rose-100 text-rose-800'
}

function formatCurrency(value: number, currency: string) {
  try {
    return new Intl.NumberFormat('es-UY', {
      style: 'currency',
      currency: currency || 'USD',
      maximumFractionDigits: 2
    }).format(value)
  } catch {
    return `${value.toFixed(2)} ${currency || ''}`
  }
}

export function MercadoLibreListings() {
  const [listings, setListings] = useState<MercadoLibreListing[]>([])
  const [statusFilter, setStatusFilter] = useState<'all' | 'active' | 'paused' | 'closed'>('all')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const filteredListings = useMemo(() => {
    if (statusFilter === 'all') return listings
    return listings.filter((listing) => listing.status === statusFilter)
  }, [listings, statusFilter])

  const loadListings = async () => {
    setLoading(true)
    setError(null)
    try {
      const params = new URLSearchParams({ limit: '30' })
      if (statusFilter !== 'all') params.append('status', statusFilter)

      const response = await fetch(`/api/mercado-libre/listings/list?${params.toString()}`)
      if (!response.ok) {
        throw new Error('No se pudieron obtener las publicaciones')
      }
      const data = await response.json()
      setListings(data.listings || [])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error desconocido')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadListings()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [statusFilter])

  const handleStatusChange = async (id: string, status: 'active' | 'paused' | 'closed') => {
    setLoading(true)
    setError(null)
    try {
      const response = await fetch('/api/mercado-libre/listings/status', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, status })
      })
      if (!response.ok) {
        const payload = await response.json().catch(() => ({}))
        throw new Error(payload?.error || 'No se pudo actualizar la publicación')
      }
      await loadListings()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error desconocido')
      setLoading(false)
    }
  }

  const summary = useMemo(() => {
    return listings.reduce(
      (acc, listing) => {
        acc.total += 1
        acc.byStatus[listing.status] = (acc.byStatus[listing.status] || 0) + 1
        acc.inventory += listing.available_quantity
        return acc
      },
      {
        total: 0,
        inventory: 0,
        byStatus: {} as Record<string, number>
      }
    )
  }, [listings])

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <div>
            <CardTitle className="text-xl font-semibold flex items-center gap-2">
              <Store className="h-5 w-5" />
              Publicaciones Mercado Libre
            </CardTitle>
            <p className="text-sm text-muted-foreground">
              Gestión centralizada de publicaciones activas, pausadas y cerradas.
            </p>
          </div>
          <div className="flex gap-2">
            <select
              value={statusFilter}
              onChange={(event) => setStatusFilter(event.target.value as any)}
              className="px-3 py-2 border rounded-md text-sm"
            >
              <option value="all">Todos los estados</option>
              <option value="active">Activos</option>
              <option value="paused">Pausados</option>
              <option value="closed">Cerrados</option>
            </select>
            <Button onClick={loadListings} disabled={loading} variant="outline">
              <RefreshCw className={`h-4 w-4 mr-2 ${loading ? 'animate-spin' : ''}`} />
              Actualizar
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
            <div className="p-4 border rounded-lg">
              <p className="text-sm text-muted-foreground">Publicaciones totales</p>
              <p className="text-2xl font-semibold">{summary.total}</p>
            </div>
            <div className="p-4 border rounded-lg">
              <p className="text-sm text-muted-foreground">Inventario disponible</p>
              <p className="text-2xl font-semibold">{summary.inventory}</p>
            </div>
            <div className="p-4 border rounded-lg">
              <p className="text-sm text-muted-foreground">Activas</p>
              <p className="text-2xl font-semibold">{summary.byStatus['active'] || 0}</p>
            </div>
          </div>

          {error && (
            <div className="mb-4 rounded bg-red-50 text-red-700 px-4 py-2 text-sm">{error}</div>
          )}

          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left border-b">
                  <th className="py-2 pr-4">Título</th>
                  <th className="py-2 pr-4">Precio</th>
                  <th className="py-2 pr-4">Stock</th>
                  <th className="py-2 pr-4">Estado</th>
                  <th className="py-2 pr-4">Acciones</th>
                </tr>
              </thead>
              <tbody>
                {filteredListings.map((listing) => (
                  <tr key={listing.id} className="border-b last:border-0">
                    <td className="py-3 pr-4">
                      <div className="flex flex-col">
                        <span className="font-medium">{listing.title}</span>
                        <a
                          href={listing.permalink}
                          target="_blank"
                          rel="noreferrer"
                          className="text-indigo-600 text-xs flex items-center gap-1"
                        >
                          Ver publicación
                          <ExternalLink className="h-3 w-3" />
                        </a>
                      </div>
                    </td>
                    <td className="py-3 pr-4">{formatCurrency(listing.price, listing.currency_id)}</td>
                    <td className="py-3 pr-4">
                      {listing.available_quantity}{' '}
                      <span className="text-muted-foreground text-xs">
                        {listing.sold_quantity
                          ? `(${listing.sold_quantity} vendidos)`
                          : 'sin ventas registradas'}
                      </span>
                    </td>
                    <td className="py-3 pr-4">
                      <Badge className={statusColors[listing.status] || 'bg-gray-100 text-gray-700'}>
                        {listing.status}
                      </Badge>
                    </td>
                    <td className="py-3 pr-4">
                      <div className="flex gap-2">
                        {listing.status !== 'paused' && (
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => handleStatusChange(listing.id, 'paused')}
                          >
                            <Pause className="h-4 w-4 mr-1" /> Pausar
                          </Button>
                        )}
                        {listing.status === 'paused' && (
                          <Button
                            size="sm"
                            onClick={() => handleStatusChange(listing.id, 'active')}
                          >
                            <Play className="h-4 w-4 mr-1" /> Reanudar
                          </Button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
                {filteredListings.length === 0 && (
                  <tr>
                    <td colSpan={5} className="py-6 text-center text-muted-foreground">
                      {loading ? 'Sincronizando publicaciones...' : 'No hay publicaciones para mostrar.'}
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

'use client'

import React, { useEffect, useMemo, useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { RefreshCw, CheckCircle, PackageCheck } from 'lucide-react'

interface StoredOrder {
  _id?: string
  orderId: number
  status: string
  totalAmount: number
  currencyId: string
  buyer: {
    full_name?: string
    nickname?: string
    email?: string
  }
  payments: Array<{
    id: number
    status: string
    transaction_amount: number
    method?: string
  }>
  shipping: {
    status?: string
    tracking_number?: string
  }
  acknowledged: boolean
  readyToShip: boolean
  dateCreated: string
}

interface OrdersSummary {
  total: number
  pending: number
  paid: number
  delivered: number
  canceled: number
  totalRevenue: number
  currency: string
}

const statusVariant: Record<string, string> = {
  paid: 'bg-emerald-100 text-emerald-800',
  pending: 'bg-yellow-100 text-yellow-800',
  canceled: 'bg-rose-100 text-rose-800',
  delivered: 'bg-blue-100 text-blue-800',
  ready_to_ship: 'bg-indigo-100 text-indigo-800'
}

function formatCurrency(value: number, currency: string) {
  try {
    return new Intl.NumberFormat('es-UY', {
      style: 'currency',
      currency: currency || 'USD'
    }).format(value)
  } catch {
    return `${value.toFixed(2)} ${currency}`
  }
}

export function MercadoLibreOrders() {
  const [orders, setOrders] = useState<StoredOrder[]>([])
  const [summary, setSummary] = useState<OrdersSummary | null>(null)
  const [loading, setLoading] = useState(false)
  const [syncing, setSyncing] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const loadOrders = async () => {
    setLoading(true)
    setError(null)
    try {
      const [ordersRes, summaryRes] = await Promise.all([
        fetch('/api/mercado-libre/orders/list'),
        fetch('/api/mercado-libre/orders/summary')
      ])

      if (!ordersRes.ok) throw new Error('No se pudieron obtener las órdenes')
      if (!summaryRes.ok) throw new Error('No se pudo obtener el resumen de órdenes')

      const ordersData = await ordersRes.json()
      const summaryData = await summaryRes.json()

      setOrders(ordersData.orders || [])
      setSummary(summaryData)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error desconocido')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadOrders()
  }, [])

  const syncOrders = async () => {
    setSyncing(true)
    setError(null)
    try {
      const response = await fetch('/api/mercado-libre/orders/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ limit: 30 })
      })

      if (!response.ok) {
        const payload = await response.json().catch(() => ({}))
        throw new Error(payload?.error || 'Error sincronizando órdenes')
      }

      await loadOrders()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error desconocido')
    } finally {
      setSyncing(false)
    }
  }

  const action = async (url: string, body: any) => {
    setError(null)
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    })
    if (!response.ok) {
      const payload = await response.json().catch(() => ({}))
      throw new Error(payload?.error || 'Error actualizando la orden')
    }
    await loadOrders()
  }

  const handleAcknowledge = async (orderId: number) => {
    try {
      await action('/api/mercado-libre/orders/acknowledge', { orderId })
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error desconocido')
    }
  }

  const handleReadyToShip = async (orderId: number) => {
    try {
      await action('/api/mercado-libre/orders/ship', { orderId })
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error desconocido')
    }
  }

  const revenuePerOrder = useMemo(() => {
    if (!summary || summary.total === 0) return '—'
    return formatCurrency(summary.totalRevenue / summary.total, summary.currency)
  }, [summary])

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <div>
          <CardTitle className="text-xl font-semibold">Órdenes y Pagos</CardTitle>
