        { value: 'failed', label: 'Failed', count: 3 }
      ]
    },
    user: {
      title: 'User',
      icon: User,
      options: [
        { value: 'all', label: 'All Users' },
        { value: 'admin', label: 'Administrators' },
        { value: 'user', label: 'Regular Users' },
        { value: 'guest', label: 'Guest Users' }
      ]
    }
  }

  const handleSearch = (query: string) => {
    setSearchQuery(query)
    onSearch(query)
  }

  const handleFilterChange = (section: string, value: string) => {
    const newFilters = { ...filters }
    if (newFilters[section] === value) {
      delete newFilters[section]
    } else {
      newFilters[section] = value
    }
    setFilters(newFilters)
    onFilterChange(newFilters)
  }

  const clearAllFilters = () => {
    setFilters({})
    onFilterChange({})
  }

  const toggleSection = (section: string) => {
    setExpandedSections(prev => ({
      ...prev,
      [section]: !prev[section]
    }))
  }

  const getActiveFiltersCount = () => {
    return Object.keys(filters).length
  }

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <Search className="h-5 w-5" />
            <span>Search & Filters</span>
            {getActiveFiltersCount() > 0 && (
              <Badge variant="secondary">{getActiveFiltersCount()}</Badge>
            )}
          </div>
          {getActiveFiltersCount() > 0 && (
            <Button
              size="sm"
              variant="outline"
              onClick={clearAllFilters}
            >
              Clear All
            </Button>
          )}
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="space-y-4">
          {/* Search Input */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <input
              type="text"
              placeholder="Search..."
              value={searchQuery}
              onChange={(e) => handleSearch(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-primary"
            />
          </div>

          {/* Filter Sections */}
          {Object.entries(filterSections).map(([sectionKey, section]) => {
            const SectionIcon = section.icon
            const isExpanded = expandedSections[sectionKey]

            return (
              <div key={sectionKey} className="space-y-2">
                <Button
                  variant="ghost"
                  className="w-full justify-between p-2 h-auto"
                  onClick={() => toggleSection(sectionKey)}
                >
                  <div className="flex items-center space-x-2">
                    <SectionIcon className="h-4 w-4" />
                    <span>{section.title}</span>
                    {filters[sectionKey] && (
                      <Badge variant="secondary" className="ml-2">
                        {section.options.find(opt => opt.value === filters[sectionKey])?.label}
                      </Badge>
                    )}
                  </div>
                  {isExpanded ? (
                    <ChevronUp className="h-4 w-4" />
                  ) : (
                    <ChevronDown className="h-4 w-4" />
                  )}
                </Button>

                {isExpanded && (
                  <div className="space-y-1 pl-6">
                    {section.options.map((option) => (
                      <div
                        key={option.value}
                        className="flex items-center justify-between p-2 rounded hover:bg-muted cursor-pointer"
                        onClick={() => handleFilterChange(sectionKey, option.value)}
                      >
                        <div className="flex items-center space-x-2">
                          <input
                            type="radio"
                            name={sectionKey}
                            value={option.value}
                            checked={filters[sectionKey] === option.value}
                            onChange={() => handleFilterChange(sectionKey, option.value)}
                            className="rounded"
                          />
                          <span className="text-sm">{option.label}</span>
                        </div>
                        {'count' in option && option.count && (
                          <Badge variant="outline" className="text-xs">
                            {option.count}
                          </Badge>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            )
          })}

          {/* Active Filters */}
          {getActiveFiltersCount() > 0 && (
            <div className="space-y-2">
              <h4 className="text-sm font-medium">Active Filters</h4>
              <div className="flex flex-wrap gap-2">
                {Object.entries(filters).map(([section, value]) => {
                  const sectionConfig = filterSections[section as keyof typeof filterSections]
                  const option = sectionConfig.options.find(opt => opt.value === value)

                  return (
                    <Badge
                      key={`${section}-${value}`}
                      variant="secondary"
                      className="flex items-center space-x-1"
                    >
                      <span>{sectionConfig.title}: {option?.label}</span>
                      <X
                        className="h-3 w-3 cursor-pointer"
                        onClick={() => handleFilterChange(section, value)}
                      />
                    </Badge>
                  )
                })}
              </div>
            </div>
          )}

          {/* Quick Actions */}
          <div className="space-y-2">
            <h4 className="text-sm font-medium">Quick Actions</h4>
            <div className="grid grid-cols-2 gap-2">
              <Button
                size="sm"
                variant="outline"
                onClick={() => {
                  setFilters({ dateRange: 'last7days' })
                  onFilterChange({ dateRange: 'last7days' })
                }}
              >
                Last 7 days
              </Button>
              <Button
                size="sm"
                variant="outline"
                onClick={() => {
                  setFilters({ status: 'active' })
                  onFilterChange({ status: 'active' })
                }}
              >
                Active only
              </Button>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  )
}

/**
 * Shared Context Service for Multi-Agent System
 * Provides unified MongoDB-based context management for all agents
 */

import { connectDB } from './mongodb'

export interface SessionMetadata {
  session_id: string
  user_phone: string
  created_at: Date
  last_activity: Date
  status: 'active' | 'expired' | 'archived'
  metadata?: {
    agent_type?: string
    source?: string
    tags?: string[]
  }
}

export interface Message {
  role: 'user' | 'assistant' | 'system'
  content: string
  timestamp: Date
  metadata?: any
}

export interface ConversationContext {
  session_id: string
  user_phone: string
  messages: Message[]
  intent?: string
  entities?: Record<string, any>
  quote_state?: {
    estado: string
    datos_cliente: Record<string, any>
    datos_producto: Record<string, any>
  }
  token_count?: number
  context_summary?: string
  last_updated: Date
}

class SharedContextService {
  private inMemorySessions: Map<string, SessionMetadata> = new Map()
  private inMemoryContexts: Map<string, ConversationContext> = new Map()

  /**
   * Retrieve full conversation context for a session
   */
  async getContext(
    sessionId: string,
    userPhone: string
  ): Promise<ConversationContext | null> {
    try {
      const db = await connectDB()
      const context = db.collection<ConversationContext>('context')

      const contextDoc = await context.findOne({
        session_id: sessionId,
        user_phone: userPhone,
      })

      if (contextDoc) {
        return contextDoc
      }

      // Fallback to in-memory
      const key = `${userPhone}_${sessionId}`
      return this.inMemoryContexts.get(key) || null
    } catch (error) {
      console.warn('Error getting context from MongoDB:', error)
      // Fallback to in-memory
      const key = `${userPhone}_${sessionId}`
      return this.inMemoryContexts.get(key) || null
    }
  }

  /**
   * Save/update conversation context
   */
  async saveContext(
    sessionId: string,
    context: ConversationContext
  ): Promise<boolean> {
    try {
      const db = await connectDB()
      const contextCol = db.collection<ConversationContext>('context')

      const contextDoc = {
        ...context,
        session_id: sessionId,
        user_phone: context.user_phone,
        last_updated: new Date(),
      }

      await contextCol.updateOne(
        { session_id: sessionId, user_phone: context.user_phone },
        { $set: contextDoc },
        { upsert: true }
      )

      // Update in-memory cache
      const key = `${context.user_phone}_${sessionId}`
      this.inMemoryContexts.set(key, contextDoc as ConversationContext)

      return true
    } catch (error) {
      console.error('Error saving context to MongoDB:', error)
      // Fallback to in-memory
      const key = `${context.user_phone}_${sessionId}`
      this.inMemoryContexts.set(key, context)
      return false
    }
  }

  /**
   * Add message to conversation history
   */
  async addMessage(
    sessionId: string,
    message: string,
    role: 'user' | 'assistant' | 'system',
    metadata?: any
  ): Promise<boolean> {
    try {
      const db = await connectDB()
      const contextCol = db.collection<ConversationContext>('context')

      const messageEntry: Message = {
        role,
        content: message,
        timestamp: new Date(),
        metadata: metadata || {},
      }

      await contextCol.updateOne(
        { session_id: sessionId },
        {
          $push: { messages: messageEntry },
          $set: { last_updated: new Date() },
        }
      )

      // Update in-memory cache
      const key = Array.from(this.inMemoryContexts.keys()).find(k =>
        k.endsWith(`_${sessionId}`)
      )
      if (key) {
        const context = this.inMemoryContexts.get(key)
        if (context) {
          context.messages.push(messageEntry)
          context.last_updated = new Date()
        }
      }

      return true
    } catch (error) {
      console.error('Error adding message:', error)
      return false
    }
  }

  /**
   * Get session metadata
   */
  async getSession(sessionId: string): Promise<SessionMetadata | null> {
    try {
      const db = await connectDB()
      const sessions = db.collection<SessionMetadata>('sessions')

      const sessionDoc = await sessions.findOne({ session_id: sessionId })

      if (sessionDoc) {
        return sessionDoc
      }

      // Fallback to in-memory
      return this.inMemorySessions.get(sessionId) || null
    } catch (error) {
      console.warn('Error getting session from MongoDB:', error)
      return this.inMemorySessions.get(sessionId) || null
    }
  }

  /**
   * Create new session
   */
  async createSession(
    userPhone: string,
    initialMessage?: string,
    metadata?: {
      agent_type?: string
      source?: string
      tags?: string[]
    }
  ): Promise<string> {
    const sessionId = `sess_${Date.now()}_${Math.random()
      .toString(36)
      .substr(2, 9)}`

    const sessionData: SessionMetadata = {
      session_id: sessionId,
      user_phone: userPhone,
      created_at: new Date(),
      last_activity: new Date(),
      status: 'active',
      metadata: metadata || {},
    }

    try {
      const db = await connectDB()
      const sessions = db.collection<SessionMetadata>('sessions')

      await sessions.insertOne(sessionData)

      // Create initial context if message provided
      if (initialMessage) {
        await this.addMessage(sessionId, initialMessage, 'user')
      }

      // Update in-memory cache
      this.inMemorySessions.set(sessionId, sessionData)

      return sessionId
    } catch (error) {
      console.warn('Error creating session in MongoDB:', error)
      // Fallback to in-memory
      this.inMemorySessions.set(sessionId, sessionData)
      if (initialMessage) {
        await this.addMessage(sessionId, initialMessage, 'user')
      }
      return sessionId
    }
  }

  /**
   * List sessions for a user or all sessions
   */
  async listSessions(
    userPhone?: string,
    limit: number = 50
  ): Promise<SessionMetadata[]> {
    try {
      const db = await connectDB()
      const sessions = db.collection<SessionMetadata>('sessions')

      const query = userPhone ? { user_phone: userPhone } : {}

      const sessionDocs = await sessions
        .find(query)
        .sort({ last_activity: -1 })
        .limit(limit)
        .toArray()

      return sessionDocs
    } catch (error) {
      console.warn('Error listing sessions from MongoDB:', error)
      // Fallback to in-memory
      const result: SessionMetadata[] = []
      const sessionsArray = Array.from(this.inMemorySessions.values())
      for (const session of sessionsArray) {
        if (!userPhone || session.user_phone === userPhone) {
          result.push(session)
        }
      }
      result.sort(
        (a, b) => b.last_activity.getTime() - a.last_activity.getTime()
      )
      return result.slice(0, limit)
    }
  }
}

// Singleton instance
let sharedContextService: SharedContextService | null = null

export function getSharedContextService(): SharedContextService {
  if (!sharedContextService) {
    sharedContextService = new SharedContextService()
  }
  return sharedContextService
}

/**
 * Context Utilities
 * Helper functions for context formatting, manipulation, and validation
 */

import { ConversationContext, Message } from './shared-context-service'

/**
 * Format context for different AI models
 */
export function formatContextForModel(
  context: ConversationContext,
  modelType: 'openai' | 'anthropic' | 'generic' = 'openai'
): any[] {
  const messages: any[] = []

  for (const msg of context.messages) {
    if (modelType === 'openai' || modelType === 'generic') {
      messages.push({
        role: msg.role,
        content: msg.content,
      })
    } else if (modelType === 'anthropic') {
      // Anthropic uses 'user' and 'assistant' roles
      messages.push({
        role: msg.role === 'system' ? 'user' : msg.role,
        content: msg.content,
      })
    }
  }

  return messages
}

/**
 * Extract key information from context
 */
export function extractKeyInfo(context: ConversationContext): {
  intent?: string
  entities?: Record<string, any>
  quoteState?: {
    estado: string
    datos_cliente: Record<string, any>
    datos_producto: Record<string, any>
  }
  lastMessage?: string
  messageCount: number
} {
  return {
    intent: context.intent,
    entities: context.entities,
    quoteState: context.quote_state,
    lastMessage:
      context.messages.length > 0
        ? context.messages[context.messages.length - 1].content
        : undefined,
    messageCount: context.messages.length,
  }
}

/**
 * Merge contexts from multiple sources
 */
export function mergeContexts(
  contexts: ConversationContext[]
): ConversationContext | null {
  if (contexts.length === 0) {
    return null
  }

  if (contexts.length === 1) {
    return contexts[0]
  }

  // Use the first context as base
  const base = { ...contexts[0] }

  // Merge messages (chronologically)
  const allMessages: Message[] = []
  for (const ctx of contexts) {
    allMessages.push(...ctx.messages)
  }

  // Sort by timestamp
  allMessages.sort((a, b) => a.timestamp.getTime() - b.timestamp.getTime())

  // Merge entities (later contexts override earlier ones)
  const mergedEntities: Record<string, any> = {}
  for (const ctx of contexts) {
    if (ctx.entities) {
      Object.assign(mergedEntities, ctx.entities)
    }
  }

  // Use the most recent intent
  const latestIntent = contexts[contexts.length - 1].intent || base.intent

  // Use the most recent quote state
  const latestQuoteState =
    contexts[contexts.length - 1].quote_state || base.quote_state

  return {
    ...base,
    messages: allMessages,
    entities: mergedEntities,
    intent: latestIntent,
    quote_state: latestQuoteState,
    last_updated: new Date(),
  }
}

/**
 * Validate context structure
 */
export function validateContext(context: any): {
  valid: boolean
  errors: string[]
} {
  const errors: string[] = []

  if (!context.session_id) {
    errors.push('Missing session_id')
  }

  if (!context.user_phone) {
    errors.push('Missing user_phone')
  }

  if (!context.messages) {
    errors.push('Missing messages array')
  } else if (!Array.isArray(context.messages)) {
    errors.push('messages must be an array')
  } else {
    // Validate each message
    for (let i = 0; i < context.messages.length; i++) {
      const msg = context.messages[i]
      if (!msg.role) {
        errors.push(`Message ${i} missing role`)
      }
      if (!['user', 'assistant', 'system'].includes(msg.role)) {
        errors.push(`Message ${i} has invalid role: ${msg.role}`)
      }
      if (!msg.content) {
        errors.push(`Message ${i} missing content`)
      }
    }
  }

  return {
    valid: errors.length === 0,
    errors,
  }
}

/**
 * Compress context by summarizing old messages
 */
export function compressContext(
  context: ConversationContext,
  keepRecent: number = 10
): ConversationContext {
  if (context.messages.length <= keepRecent) {
    return context
  }

  // Keep recent messages
  const recentMessages = context.messages.slice(-keepRecent)

  // Create summary of older messages
  const oldMessages = context.messages.slice(0, -keepRecent)
  const summaryMessage: Message = {
    role: 'system',
    content: `Previous conversation summary: ${
      oldMessages.length
    } messages about ${context.intent || 'general topics'}`,
    timestamp: new Date(),
  }

  return {
    ...context,
    messages: [summaryMessage, ...recentMessages],
    context_summary: `Compressed from ${context.messages.length} to ${
      keepRecent + 1
    } messages`,
    last_updated: new Date(),
  }
}

/**
 * Extract conversation summary
 */
export function getConversationSummary(context: ConversationContext): string {
  if (context.context_summary) {
    return context.context_summary
  }

  const keyInfo = extractKeyInfo(context)
  const parts: string[] = []

  if (keyInfo.intent) {
    parts.push(`Intent: ${keyInfo.intent}`)
  }

  if (keyInfo.quoteState) {
    parts.push(`Quote state: ${keyInfo.quoteState.estado}`)
  }

  parts.push(`${keyInfo.messageCount} messages exchanged`)

  return parts.join('. ')
}

/**
 * Simple System Initialization
 * Provides basic system status and initialization functions
 */

export interface SystemStatus {
  initialized: boolean
  timestamp: string
  version?: string
}

let systemInitialized = false
let initializationTimestamp: string | null = null

/**
 * Initialize the simple system
 * @returns Promise with initialization result
 */
export async function initializeSimpleSystem(): Promise<{
  success: boolean
  timestamp: string
}> {
  if (!systemInitialized) {
    systemInitialized = true
    initializationTimestamp = new Date().toISOString()
  }

  return {
    success: true,
    timestamp: initializationTimestamp || new Date().toISOString(),
  }
}

/**
 * Get current system status
 * @returns System status object
 */
export function getSystemStatus(): SystemStatus {
  return {
    initialized: systemInitialized,
    timestamp: initializationTimestamp || new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0',
  }
}

import { google } from 'googleapis'
import { secureConfig } from './secure-config'

export interface AdminRow {
  rowNumber: number
  arg: string
  estado: string
  fecha: string
  cliente: string
  origen: string
  telefono: string
  direccion: string
  consulta: string
}

export interface QuoteData {
  arg: string
  estado: string
  fecha: string
  cliente: string
  origen: string
  telefono: string
  direccion: string
  consulta: string
}

export class GoogleSheetsClient {
  private sheets: any
  private spreadsheetId: string

  constructor() {
    if (!secureConfig.isReady()) {
      throw new Error('SecureConfig not initialized. Call initializeSecureConfig() first.')
    }

    const config = secureConfig.getGoogleSheetsConfig()
    this.spreadsheetId = config.sheetId

    if (!this.spreadsheetId) {
      throw new Error('Google Sheet ID is not configured')
    }

    const auth = new google.auth.GoogleAuth({
      credentials: {
        client_email: config.serviceAccountEmail,
        private_key: config.privateKey?.replace(/\\n/g, '\n')
      },
      scopes: config.scopes
    })

    this.sheets = google.sheets({ version: 'v4', auth })
  }

  // Leer pestaña "Admin." completa
  async readAdminTab(): Promise<AdminRow[]> {
    try {
      const response = await this.sheets.spreadsheets.values.get({
        spreadsheetId: this.spreadsheetId,
        range: 'Admin.!A:H' // Columnas A-H
      })
      return this.parseAdminRows(response.data.values || [])
    } catch (error) {
      console.error('Error reading Admin tab:', error)
      throw new Error(`Failed to read Admin tab: ${error instanceof Error ? error.message : String(error)}`)
    }
  }

  // Leer pestaña "Enviados"
  async readEnviadosTab(): Promise<AdminRow[]> {
    try {
      const response = await this.sheets.spreadsheets.values.get({
        spreadsheetId: this.spreadsheetId,
        range: 'Enviados!A:H'
      })
      return this.parseAdminRows(response.data.values || [])
    } catch (error) {
      console.error('Error reading Enviados tab:', error)
      throw new Error(`Failed to read Enviados tab: ${error instanceof Error ? error.message : String(error)}`)
    }
  }

  // Leer pestaña "Confirmado"
  async readConfirmadoTab(): Promise<AdminRow[]> {
    try {
      const response = await this.sheets.spreadsheets.values.get({
        spreadsheetId: this.spreadsheetId,
        range: 'Confirmado!A:H'
      })
      return this.parseAdminRows(response.data.values || [])
    } catch (error) {
      console.error('Error reading Confirmado tab:', error)
      throw new Error(`Failed to read Confirmado tab: ${error instanceof Error ? error.message : String(error)}`)
    }
  }

  // Parsear filas del sheet
  private parseAdminRows(rows: any[][]): AdminRow[] {
    if (!rows || rows.length === 0) return []

    // Primera fila son headers, saltarla
    return rows.slice(1).map((row, index) => ({
      rowNumber: index + 2, // +2 porque Excel empieza en 1 y saltamos header
      arg: row[0] || '',
      estado: row[1] || '',
      fecha: row[2] || '',
      cliente: row[3] || '',
      origen: row[4] || '',
      telefono: row[5] || '',
      direccion: row[6] || '',
      consulta: row[7] || '',
    }))
  }

  // Agregar nueva cotización a "Admin."
  async addQuoteToAdmin(quoteData: QuoteData): Promise<void> {
    try {
      const values = [[
        quoteData.arg,
        quoteData.estado,
        quoteData.fecha,
        quoteData.cliente,
        quoteData.origen,
        quoteData.telefono,
        quoteData.direccion,
        quoteData.consulta
      ]]

      await this.sheets.spreadsheets.values.append({
        spreadsheetId: this.spreadsheetId,
        range: 'Admin.!A:H',
        valueInputOption: 'USER_ENTERED',
        resource: { values }
      })
    } catch (error) {
      console.error('Error adding quote to Admin:', error)
      throw new Error(`Failed to add quote to Admin: ${error instanceof Error ? error.message : String(error)}`)
    }
  }

  // Leer fila específica
  async readSpecificRow(sheetName: string, rowNumber: number): Promise<string[]> {
    try {
      const response = await this.sheets.spreadsheets.values.get({
        spreadsheetId: this.spreadsheetId,
        range: `${sheetName}!A${rowNumber}:H${rowNumber}`
      })
      return response.data.values?.[0] || []
    } catch (error) {
      console.error(`Error reading specific row ${rowNumber} from ${sheetName}:`, error)
      throw new Error(`Failed to read row ${rowNumber} from ${sheetName}: ${error instanceof Error ? error.message : String(error)}`)
    }
  }

  // Mover cotización de "Admin." a "Enviados"
  async moveToEnviados(rowNumber: number, additionalData?: any): Promise<void> {
    try {
      // 1. Leer la fila específica
      const row = await this.readSpecificRow('Admin.', rowNumber)

      // 2. Agregar a "Enviados"
      await this.sheets.spreadsheets.values.append({
        spreadsheetId: this.spreadsheetId,
        range: 'Enviados!A:H',
        valueInputOption: 'USER_ENTERED',
        resource: { values: [row] }
      })

      // 3. Cambiar estado en "Admin." en lugar de eliminar
      await this.updateCellValue('Admin.', rowNumber, 'B', 'Enviado')
    } catch (error) {
      console.error('Error moving to Enviados:', error)
      throw new Error(`Failed to move to Enviados: ${error instanceof Error ? error.message : String(error)}`)
    }
  }

  // Mover cotización de "Enviados" a "Confirmado"
  async moveToConfirmado(rowNumber: number): Promise<void> {
    try {
      // 1. Leer la fila específica de Enviados
      const row = await this.readSpecificRow('Enviados', rowNumber)

      // 2. Agregar a "Confirmado"
      await this.sheets.spreadsheets.values.append({
        spreadsheetId: this.spreadsheetId,
        range: 'Confirmado!A:H',
        valueInputOption: 'USER_ENTERED',
        resource: { values: [row] }
      })

      // 3. Cambiar estado en "Enviados"
      await this.updateCellValue('Enviados', rowNumber, 'B', 'Confirmado')
    } catch (error) {
      console.error('Error moving to Confirmado:', error)
      throw new Error(`Failed to move to Confirmado: ${error instanceof Error ? error.message : String(error)}`)
    }
  }

  // Actualizar valor de una celda específica
  async updateCellValue(sheetName: string, row: number, column: string, value: string): Promise<void> {
    try {
      await this.sheets.spreadsheets.values.update({
        spreadsheetId: this.spreadsheetId,
        range: `${sheetName}!${column}${row}`,
        valueInputOption: 'USER_ENTERED',
        resource: { values: [[value]] }
      })
    } catch (error) {
      console.error(`Error updating cell ${column}${row} in ${sheetName}:`, error)
      throw new Error(`Failed to update cell: ${error instanceof Error ? error.message : String(error)}`)
    }
  }

  // Buscar cotización por teléfono
  async findByPhone(phone: string): Promise<{
    pendientes: AdminRow[]
    enviados: AdminRow[]
    confirmados: AdminRow[]
  }> {
    try {
      const [adminRows, enviadosRows, confirmadosRows] = await Promise.all([
        this.readAdminTab(),
        this.readEnviadosTab(),
        this.readConfirmadoTab()
      ])

      return {
        pendientes: adminRows.filter(r => r.telefono.includes(phone)),
        enviados: enviadosRows.filter(r => r.telefono.includes(phone)),
        confirmados: confirmadosRows.filter(r => r.telefono.includes(phone))
      }
    } catch (error) {
      console.error('Error finding by phone:', error)
      throw new Error(`Failed to find by phone: ${error instanceof Error ? error.message : String(error)}`)
    }
  }

  // Obtener estadísticas generales
  async getStats(): Promise<{
    totalPendientes: number
    totalEnviados: number
    totalConfirmados: number
    totalGeneral: number
  }> {
    try {
      const [adminRows, enviadosRows, confirmadosRows] = await Promise.all([
        this.readAdminTab(),
        this.readEnviadosTab(),
        this.readConfirmadoTab()
      ])

      return {
        totalPendientes: adminRows.length,
        totalEnviados: enviadosRows.length,
        totalConfirmados: confirmadosRows.length,
        totalGeneral: adminRows.length + enviadosRows.length + confirmadosRows.length
      }
    } catch (error) {
      console.error('Error getting stats:', error)
      throw new Error(`Failed to get stats: ${error instanceof Error ? error.message : String(error)}`)
    }
  }

  // Generar código Arg automático
  generateArgCode(phone: string, origen: string = 'WA'): string {
    const prefix = phone.slice(-4)
    const date = new Date().getDate()
    const month = new Date().getMonth() + 1
    return `${origen}${month}${date}${prefix}`
  }
}

import { getDatabase } from './mongodb'
import { Quote, QuoteStats } from '@/models/Quote'

export class QuoteService {
  private collectionName = 'quotes'

  async createQuote(quoteData: Omit<Quote, '_id' | 'createdAt' | 'updatedAt'>): Promise<Quote> {
    const db = await getDatabase()
    const collection = db.collection(this.collectionName)

    const quote: Quote = {
      ...quoteData,
      createdAt: new Date(),
      updatedAt: new Date(),
      history: [{
        timestamp: new Date(),
        action: 'created',
        newValue: quoteData
      }]
    }

    const result = await collection.insertOne(quote as any)
    return { ...quote, _id: result.insertedId.toString() } as Quote
  }

  async getQuoteById(id: string): Promise<Quote | null> {
    const db = await getDatabase()
    const collection = db.collection(this.collectionName)

    const quote = await collection.findOne({ _id: id } as any)
    return quote as any as Quote | null
  }

  async getQuoteByArg(arg: string): Promise<Quote | null> {
    const db = await getDatabase()
    const collection = db.collection(this.collectionName)

    const quote = await collection.findOne({ arg })
    return quote as any as Quote | null
  }

  async getQuotesByPhone(phone: string): Promise<Quote[]> {
    const db = await getDatabase()
    const collection = db.collection(this.collectionName)

    const quotes = await collection.find({ telefono: { $regex: phone, $options: 'i' } })
      .sort({ createdAt: -1 })
      .toArray()

    return quotes as any as Quote[]
  }

  async updateQuoteStatus(arg: string, newStatus: Quote['estado'], user?: string): Promise<boolean> {
    const db = await getDatabase()
    const collection = db.collection(this.collectionName)

    const quote = await this.getQuoteByArg(arg)
    if (!quote) return false

    const oldStatus = quote.estado

    const result = await collection.updateOne(
      { arg } as any,
      {
        $set: {
          estado: newStatus,
          updatedAt: new Date()
        },
        $push: {
          history: {
            timestamp: new Date(),
            action: 'status_update',
            oldValue: oldStatus,
            newValue: newStatus,
            user
          } as any
        } as any
      }
    )

    return result.modifiedCount > 0
  }

  async updateQuoteParsedData(arg: string, parsedData: Quote['parsed']): Promise<boolean> {
    const db = await getDatabase()
    const collection = db.collection(this.collectionName)

    const result = await collection.updateOne(
      { arg },
      {
        $set: {
          parsed: parsedData,
          updatedAt: new Date()
        },
        $push: {
          history: {
            timestamp: new Date(),
            action: 'parsed_data_update',
            newValue: parsedData
          } as any
        } as any
      }
    )

    return result.modifiedCount > 0
  }

  async getQuotesByEstado(estado: Quote['estado']): Promise<Quote[]> {
    const db = await getDatabase()
    const collection = db.collection(this.collectionName)

    const quotes = await collection.find({ estado })
      .sort({ createdAt: -1 })
      .toArray()

    return quotes as any as Quote[]
  }

  async getAllQuotes(limit: number = 100, skip: number = 0): Promise<Quote[]> {
    const db = await getDatabase()
    const collection = db.collection(this.collectionName)

    const quotes = await collection.find({})
      .sort({ createdAt: -1 })
      .skip(skip)
      .limit(limit)
      .toArray()

    return quotes as any as Quote[]
  }

  async getStats(): Promise<QuoteStats> {
    const db = await getDatabase()
    const collection = db.collection(this.collectionName)

    const [totalPendientes, totalEnviados, totalConfirmados, totalGeneral] = await Promise.all([
      collection.countDocuments({ estado: 'Pendiente' }),
      collection.countDocuments({ estado: 'Enviado' }),
      collection.countDocuments({ estado: 'Confirmado' }),
      collection.countDocuments({})
    ])

    // Estadísticas por origen
    const porOrigen = await collection.aggregate([
      { $group: { _id: '$origen', count: { $sum: 1 } } }
    ]).toArray()

    const porOrigenMap = {
      WA: 0,
      LO: 0,
      EM: 0,
      CL: 0
    }

    porOrigen.forEach((item: any) => {
      if (item._id in porOrigenMap) {
        porOrigenMap[item._id as keyof typeof porOrigenMap] = item.count
      }
    })

    // Estadísticas por estado
    const porEstado = await collection.aggregate([
      { $group: { _id: '$estado', count: { $sum: 1 } } }
    ]).toArray()

    const porEstadoMap = {
      Pendiente: 0,
      Adjunto: 0,
      Listo: 0,
      Enviado: 0,
      Asignado: 0,
      Confirmado: 0
    }

    porEstado.forEach((item: any) => {
      if (item._id in porEstadoMap) {
        porEstadoMap[item._id as keyof typeof porEstadoMap] = item.count
      }
    })

    return {
      totalPendientes,
      totalEnviados,
      totalConfirmados,
      totalGeneral,
      porOrigen: porOrigenMap,
      porEstado: porEstadoMap,
      ultimaActualizacion: new Date()
    }
  }

  async searchQuotes(query: string): Promise<Quote[]> {
    const db = await getDatabase()
    const collection = db.collection(this.collectionName)

    const quotes = await collection.find({
      $or: [
        { cliente: { $regex: query, $options: 'i' } },
        { consulta: { $regex: query, $options: 'i' } },
        { arg: { $regex: query, $options: 'i' } },
        { telefono: { $regex: query, $options: 'i' } }
      ]
    })
      .sort({ createdAt: -1 })
      .limit(50)
      .toArray()

    return quotes as any as Quote[]
  }

  async deleteQuote(arg: string): Promise<boolean> {
    const db = await getDatabase()
    const collection = db.collection(this.collectionName)

    const result = await collection.deleteOne({ arg })
    return result.deletedCount > 0
  }
}

import crypto from 'crypto'

interface Credentials {
  openai: {
    api_key: string
    model: string
    max_tokens: number
    temperature: number
  }
  google_sheets: {
    sheet_id: string
    service_account_email: string
    private_key: string
    scopes: string[]
  }
  mongodb: {
    uri: string
    database: string
    collections: {
      quotes: string
      sessions: string
      context: string
      analytics: string
    }
  }
  whatsapp: {
    access_token: string
    phone_number_id: string
    verify_token: string
    webhook_url: string
  }
  n8n: {
    webhook_url: string
    api_key: string
    base_url: string
  }
  mercado_libre: {
    app_id: string
    client_secret: string
    redirect_uri: string
    seller_id: string
    webhook_secret: string
    auth_base_url: string
    api_base_url: string
    scopes: string[]
    pkce_enabled: boolean
  }
  system: {
    environment: string
    max_context_tokens: number
    max_messages_per_session: number
    inactivity_timeout_minutes: number
    default_zone: string
    encryption_key: string
  }
}

class CredentialsManager {
  private credentials: Credentials | null = null
  private encryptionKey: string
  private isLoaded = false

  constructor() {
    // Usar clave de encriptación del sistema o generar una
    this.encryptionKey = process.env.CREDENTIALS_ENCRYPTION_KEY || 
      'bmc-default-encryption-key-32-chars'
  }

  // Cargar credenciales desde archivo JSON encriptado
  async loadCredentials(credentialsPath: string = './credentials.json'): Promise<void> {
    try {
      let loadedFromFile = false

      if (process.env.NODE_ENV === 'development') {
        try {
          const fs = await import('fs/promises')
          const path = await import('path')

          const fullPath = path.resolve(process.cwd(), credentialsPath)
          const encryptedData = await fs.readFile(fullPath, 'utf-8')

          // Desencriptar datos
          const decryptedData = this.decrypt(encryptedData)
          this.credentials = JSON.parse(decryptedData)
          loadedFromFile = true
        } catch (fileError: any) {
          if (fileError?.code === 'ENOENT') {
            console.warn('⚠️ credentials.json no encontrado, usando variables de entorno')
            this.loadFromEnvironment()
          } else {
            throw fileError
          }
        }
      } else {
        this.loadFromEnvironment()
      }

      if (!loadedFromFile && !this.credentials) {
        this.loadFromEnvironment()
      }

      this.isLoaded = true
      console.log('✅ Credenciales cargadas exitosamente')
    } catch (error) {
      console.error('❌ Error cargando credenciales:', error)
      throw new Error('No se pudieron cargar las credenciales')
    }
  }

  // Cargar credenciales desde variables de entorno
  private loadFromEnvironment(): void {
    this.credentials = {
      openai: {
        api_key: process.env.OPENAI_API_KEY || '',
        model: process.env.OPENAI_MODEL || 'gpt-4',
        max_tokens: parseInt(process.env.OPENAI_MAX_TOKENS || '4000'),
        temperature: parseFloat(process.env.OPENAI_TEMPERATURE || '0.1')
      },
      google_sheets: {
        sheet_id: process.env.GOOGLE_SHEET_ID || '',
        service_account_email: process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL || '',
        private_key: process.env.GOOGLE_PRIVATE_KEY || '',
        scopes: ['https://www.googleapis.com/auth/spreadsheets']
      },
      mongodb: {
        uri: process.env.MONGODB_URI || '',
        database: process.env.MONGODB_DATABASE || 'bmc_quotes',
        collections: {
          quotes: process.env.MONGODB_QUOTES_COLLECTION || 'quotes',
          sessions: process.env.MONGODB_SESSIONS_COLLECTION || 'sessions',
          context: process.env.MONGODB_CONTEXT_COLLECTION || 'context',
          analytics: process.env.MONGODB_ANALYTICS_COLLECTION || 'analytics'
        }
      },
      whatsapp: {
        access_token: process.env.WHATSAPP_ACCESS_TOKEN || '',
        phone_number_id: process.env.WHATSAPP_PHONE_NUMBER_ID || '',
        verify_token: process.env.WHATSAPP_VERIFY_TOKEN || 'bmc_whatsapp_verify_2024',
        webhook_url: process.env.WHATSAPP_WEBHOOK_URL || ''
      },
      n8n: {
        webhook_url: process.env.N8N_WEBHOOK_URL || 'http://localhost:5678/webhook/bmc-quotes',
        api_key: process.env.N8N_API_KEY || '',
        base_url: process.env.N8N_BASE_URL || 'http://localhost:5678'
      },
      mercado_libre: {
        app_id: process.env.MERCADO_LIBRE_APP_ID || process.env.MELI_APP_ID || '',
        client_secret: process.env.MERCADO_LIBRE_CLIENT_SECRET || process.env.MELI_CLIENT_SECRET || '',
        redirect_uri: process.env.MERCADO_LIBRE_REDIRECT_URI || process.env.MELI_REDIRECT_URI || '',
        seller_id: process.env.MERCADO_LIBRE_SELLER_ID || process.env.MELI_SELLER_ID || '',
        webhook_secret: process.env.MERCADO_LIBRE_WEBHOOK_SECRET || '',
        auth_base_url: process.env.MERCADO_LIBRE_AUTH_URL || 'https://auth.mercadolibre.com.ar',
        api_base_url: process.env.MERCADO_LIBRE_API_URL || 'https://api.mercadolibre.com',
        scopes: (process.env.MERCADO_LIBRE_SCOPES || 'offline_access read write')
          .split(/[ ,]+/)
          .filter(Boolean),
        pkce_enabled: (process.env.MERCADO_LIBRE_PKCE_ENABLED || 'true').toLowerCase() !== 'false'
      },
      system: {
        environment: process.env.NODE_ENV || 'development',
        max_context_tokens: parseInt(process.env.MAX_CONTEXT_TOKENS || '8000'),
        max_messages_per_session: parseInt(process.env.MAX_MESSAGES_PER_SESSION || '20'),
        inactivity_timeout_minutes: parseInt(process.env.INACTIVITY_TIMEOUT_MINUTES || '30'),
        default_zone: process.env.DEFAULT_ZONE || 'montevideo',
        encryption_key: this.encryptionKey
      }
    }
  }

  // Obtener credenciales específicas
  getOpenAI() {
    this.ensureLoaded()
    return this.credentials!.openai
  }

  getGoogleSheets() {
    this.ensureLoaded()
    return this.credentials!.google_sheets
  }

  getMongoDB() {
    this.ensureLoaded()
    return this.credentials!.mongodb
  }

  getWhatsApp() {
    this.ensureLoaded()
    return this.credentials!.whatsapp
  }

  getN8N() {
    this.ensureLoaded()
    return this.credentials!.n8n
  }

  getMercadoLibre() {
    this.ensureLoaded()
    return this.credentials!.mercado_libre
  }

  getSystem() {
    this.ensureLoaded()
    return this.credentials!.system
  }

  // Verificar si todas las credenciales están configuradas
  validateCredentials(): { isValid: boolean; missing: string[] } {
    this.ensureLoaded()

    const missing: string[] = []
    const creds = this.credentials!

    // Verificar OpenAI
    if (!creds.openai.api_key) missing.push('OPENAI_API_KEY')

    // Verificar Google Sheets
    if (!creds.google_sheets.sheet_id) missing.push('GOOGLE_SHEET_ID')
    if (!creds.google_sheets.service_account_email) missing.push('GOOGLE_SERVICE_ACCOUNT_EMAIL')
    if (!creds.google_sheets.private_key) missing.push('GOOGLE_PRIVATE_KEY')

    // Verificar MongoDB
    if (!creds.mongodb.uri) missing.push('MONGODB_URI')

    // Verificar WhatsApp (opcional)
    if (!creds.whatsapp.access_token) missing.push('WHATSAPP_ACCESS_TOKEN')
    if (!creds.whatsapp.phone_number_id) missing.push('WHATSAPP_PHONE_NUMBER_ID')

    // Verificar Mercado Libre
    if (!creds.mercado_libre.app_id) missing.push('MERCADO_LIBRE_APP_ID')
    if (!creds.mercado_libre.client_secret) missing.push('MERCADO_LIBRE_CLIENT_SECRET')
    if (!creds.mercado_libre.redirect_uri) missing.push('MERCADO_LIBRE_REDIRECT_URI')
    if (!creds.mercado_libre.seller_id) missing.push('MERCADO_LIBRE_SELLER_ID')

    return {
      isValid: missing.length === 0,
      missing
    }
  }

  // Encriptar datos sensibles
  private encrypt(text: string): string {
    const cipher = crypto.createCipher('aes-256-cbc', this.encryptionKey)
    let encrypted = cipher.update(text, 'utf8', 'hex')
    encrypted += cipher.final('hex')
    return encrypted
  }

  // Desencriptar datos sensibles
  private decrypt(encryptedText: string): string {
    const decipher = crypto.createDecipher('aes-256-cbc', this.encryptionKey)
    let decrypted = decipher.update(encryptedText, 'hex', 'utf8')
    decrypted += decipher.final('utf8')
    return decrypted
  }

  // Verificar que las credenciales estén cargadas
  private ensureLoaded(): void {
    if (!this.isLoaded || !this.credentials) {
      throw new Error('Las credenciales no han sido cargadas. Llama a loadCredentials() primero.')
    }
  }

  // Obtener resumen de credenciales (sin datos sensibles)
  getCredentialsSummary() {
    this.ensureLoaded()

    return {
      openai: {
        model: this.credentials!.openai.model,
        max_tokens: this.credentials!.openai.max_tokens,
        has_api_key: !!this.credentials!.openai.api_key
      },
      google_sheets: {
        sheet_id: this.credentials!.google_sheets.sheet_id,
        has_credentials: !!(this.credentials!.google_sheets.service_account_email && this.credentials!.google_sheets.private_key)
      },
      mongodb: {
        database: this.credentials!.mongodb.database,
        has_uri: !!this.credentials!.mongodb.uri
      },
      whatsapp: {
        has_credentials: !!(this.credentials!.whatsapp.access_token && this.credentials!.whatsapp.phone_number_id)
      },
      mercado_libre: {
        app_id: this.credentials!.mercado_libre.app_id,
        has_secret: !!this.credentials!.mercado_libre.client_secret,
        seller_id: this.credentials!.mercado_libre.seller_id,
        pkce_enabled: this.credentials!.mercado_libre.pkce_enabled,
        scopes: this.credentials!.mercado_libre.scopes
      },
      n8n: {
        webhook_url: this.credentials!.n8n.webhook_url,
        has_api_key: !!this.credentials!.n8n.api_key
      },
      system: {
        environment: this.credentials!.system.environment,
        max_context_tokens: this.credentials!.system.max_context_tokens
      }
    }
  }
}

// Instancia global del gestor de credenciales
export const credentialsManager = new CredentialsManager()

// Función de conveniencia para inicializar credenciales
export async function initializeCredentials(credentialsPath?: string): Promise<void> {
  await credentialsManager.loadCredentials(credentialsPath)

  const validation = credentialsManager.validateCredentials()
  if (!validation.isValid) {
    console.warn('⚠️ Credenciales faltantes:', validation.missing)
    console.log('💡 Usa el archivo credentials-template.json como guía')
  } else {
    console.log('✅ Todas las credenciales están configuradas correctamente')
  }
}

import { type ClassValue, clsx } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function formatNumber(num: number): string {
  return new Intl.NumberFormat('en-US').format(num)
}

export function formatCurrency(amount: number, currency: string = 'USD'): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: currency,
  }).format(amount)
}

export function formatPercentage(value: number, decimals: number = 1): string {
  return `${(value * 100).toFixed(decimals)}%`
}

export function formatDuration(seconds: number): string {
  if (seconds < 60) {
    return `${seconds.toFixed(1)}s`
  } else if (seconds < 3600) {
    return `${(seconds / 60).toFixed(1)}m`
  } else {
    return `${(seconds / 3600).toFixed(1)}h`
  }
}

export function getStatusColor(status: string): string {
  switch (status.toLowerCase()) {
    case 'success':
    case 'online':
    case 'active':
      return 'text-green-600 bg-green-100 dark:text-green-400 dark:bg-green-900/20'
    case 'warning':
    case 'pending':
      return 'text-yellow-600 bg-yellow-100 dark:text-yellow-400 dark:bg-yellow-900/20'
    case 'error':
    case 'offline':
    case 'inactive':
      return 'text-red-600 bg-red-100 dark:text-red-400 dark:bg-red-900/20'
    case 'info':
    case 'processing':
      return 'text-blue-600 bg-blue-100 dark:text-blue-400 dark:bg-blue-900/20'
    default:
      return 'text-gray-600 bg-gray-100 dark:text-gray-400 dark:bg-gray-900/20'
  }
}

export function getTrendIcon(trend: 'up' | 'down' | 'neutral'): string {
  switch (trend) {
    case 'up':
      return '↗️'
    case 'down':
      return '↘️'
    default:
      return '→'
  }
}

export function getTrendColor(trend: 'up' | 'down' | 'neutral'): string {
  switch (trend) {
    case 'up':
      return 'text-green-600'
    case 'down':
      return 'text-red-600'
    default:
      return 'text-gray-600'
  }
}

export function calculatePercentageChange(current: number, previous: number): number {
  if (previous === 0) return current > 0 ? 100 : 0
  return ((current - previous) / previous) * 100
}

export function getPercentageChangeColor(change: number): string {
  if (change > 0) return 'text-green-600'
  if (change < 0) return 'text-red-600'
  return 'text-gray-600'
}

export function truncateText(text: string, maxLength: number): string {
  if (text.length <= maxLength) return text
  return text.slice(0, maxLength) + '...'
}

export function generateId(): string {
  return Math.random().toString(36).substr(2, 9)
}

export function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number
): (...args: Parameters<T>) => void {
  let timeout: NodeJS.Timeout
  return (...args: Parameters<T>) => {
    clearTimeout(timeout)
    timeout = setTimeout(() => func(...args), wait)
  }
}

export function throttle<T extends (...args: any[]) => any>(
  func: T,
  limit: number
): (...args: Parameters<T>) => void {
  let inThrottle: boolean
  return (...args: Parameters<T>) => {
    if (!inThrottle) {
      func(...args)
      inThrottle = true
      setTimeout(() => (inThrottle = false), limit)
    }
  }
}

