  setInterval(() => {
    const now = Date.now()
    // Use Array.from to avoid iteration issues with older TypeScript targets
    for (const [key, record] of Array.from(rateLimitMap.entries())) {
      if (now > record.resetTime) {
        rateLimitMap.delete(key)
      }
    }
  }, 5 * 60 * 1000) // 5 minutes
}

/**
 * Gets client identifier from request
 * @param request - Next.js request object
 * @returns Client identifier (IP address or user ID)
 */
function getClientId(request: NextRequest): string {
  // Try to get IP from various headers (for proxied requests)
  const forwardedFor = request.headers.get('x-forwarded-for')
  const realIp = request.headers.get('x-real-ip')
  const cfConnectingIp = request.headers.get('cf-connecting-ip')

  if (forwardedFor) {
    // x-forwarded-for can contain multiple IPs, take the first one
    return forwardedFor.split(',')[0].trim()
  }

  if (realIp) {
    return realIp
  }

  if (cfConnectingIp) {
    return cfConnectingIp
  }

  // Fallback to a default identifier
  return 'unknown'
}

/**
 * Rate limit check
 * @param request - Next.js request object
 * @param maxRequests - Maximum requests allowed in the window
 * @param windowMs - Time window in milliseconds
 * @returns Object with allowed status and remaining requests
 */
export function rateLimit(
  request: NextRequest,
  maxRequests: number = 100,
  windowMs: number = 15 * 60 * 1000 // 15 minutes default
): { allowed: boolean; remaining: number; resetTime: number } {
  const clientId = getClientId(request)
  const now = Date.now()

  // Get or create rate limit record
  let record = rateLimitMap.get(clientId)

  // If no record or window expired, create new record
  if (!record || now > record.resetTime) {
    record = {
      count: 1,
      resetTime: now + windowMs,
    }
    rateLimitMap.set(clientId, record)
    return {
      allowed: true,
      remaining: maxRequests - 1,
      resetTime: record.resetTime,
    }
  }

  // Check if limit exceeded
  if (record.count >= maxRequests) {
    return {
      allowed: false,
      remaining: 0,
      resetTime: record.resetTime,
    }
  }

  // Increment count
  record.count++
  return {
    allowed: true,
    remaining: maxRequests - record.count,
    resetTime: record.resetTime,
  }
}

/**
 * Rate limit middleware wrapper
 * @param handler - Route handler function
 * @param maxRequests - Maximum requests allowed
 * @param windowMs - Time window in milliseconds
 * @returns Wrapped handler with rate limiting
 */
export function withRateLimit(
  handler: (request: NextRequest) => Promise<NextResponse>,
  maxRequests: number = 100,
  windowMs: number = 15 * 60 * 1000
) {
  return async (request: NextRequest) => {
    const limitResult = rateLimit(request, maxRequests, windowMs)

    if (!limitResult.allowed) {
      return NextResponse.json(
        {
          success: false,
          error: 'Rate limit exceeded',
          message: `Too many requests. Please try again after ${new Date(
            limitResult.resetTime
          ).toISOString()}`,
          resetTime: limitResult.resetTime,
        },
        {
          status: 429,
          headers: {
            'X-RateLimit-Limit': maxRequests.toString(),
            'X-RateLimit-Remaining': '0',
            'X-RateLimit-Reset': limitResult.resetTime.toString(),
            'Retry-After': Math.ceil(
              (limitResult.resetTime - Date.now()) / 1000
            ).toString(),
          },
        }
      )
    }

    // Add rate limit headers to response
    const response = await handler(request)
    response.headers.set('X-RateLimit-Limit', maxRequests.toString())
    response.headers.set(
      'X-RateLimit-Remaining',
      limitResult.remaining.toString()
    )
    response.headers.set('X-RateLimit-Reset', limitResult.resetTime.toString())

    return response
  }
}

/**
 * Combined authentication and rate limiting middleware
 * @param handler - Route handler function
 * @param options - Configuration options
 * @returns Wrapped handler with auth and rate limiting
 */
export function withAuthAndRateLimit(
  handler: (request: NextRequest, user: any) => Promise<NextResponse>,
  options: {
    requireAuth?: boolean
    requireAdmin?: boolean
    maxRequests?: number
    windowMs?: number
  } = {}
) {
  const {
    requireAuth: needsAuth = false,
    requireAdmin: needsAdmin = false,
    maxRequests = 100,
    windowMs = 15 * 60 * 1000,
  } = options

  return withRateLimit(
    async (request: NextRequest) => {
      // Handle authentication if required
      if (needsAuth || needsAdmin) {
        const token = request.headers.get('Authorization')

        if (!token) {
          return NextResponse.json(
            { success: false, error: 'Unauthorized - Missing token' },
            { status: 401 }
          )
        }

        // Import auth functions dynamically to avoid circular dependencies
        const { validateToken, checkAdminRole } = await import('./auth')
        const user = await validateToken(token)

        if (!user) {
          return NextResponse.json(
            { success: false, error: 'Unauthorized - Invalid token' },
            { status: 401 }
          )
        }

        if (needsAdmin && !checkAdminRole(user)) {
          return NextResponse.json(
            { success: false, error: 'Forbidden - Admin access required' },
            { status: 403 }
          )
        }

        return handler(request, user)
      }

      return handler(request, null)
    },
    maxRequests,
    windowMs
  )
}

/**
 * Authentication Middleware for Next.js API Routes
 * Provides authentication and authorization utilities
 */

import { NextRequest, NextResponse } from 'next/server'

import { AuthenticatedUser, User } from '@/types/user'

export type AuthUser = User

/**
 * Validates an authentication token
 * @param token - Bearer token from Authorization header
 * @returns User object if valid, null otherwise
 */
export async function validateToken(token: string): Promise<AuthUser | null> {
  // Remove 'Bearer ' prefix if present
  const cleanToken = token.replace(/^Bearer\s+/i, '')

  // For now, use environment variable for simple API key authentication
  // In production, implement proper JWT validation or OAuth
  const apiKey = process.env.API_KEY || process.env.ADMIN_API_KEY

  if (!apiKey) {
    // If no API key configured, allow all requests (development mode)
    // In production, this should be required
    if (process.env.NODE_ENV === 'production') {
      return null
    }
    return { id: 'dev-user', role: 'admin' }
  }

  // Simple API key validation
  if (cleanToken === apiKey) {
    return { id: 'api-user', role: 'admin' }
  }

  // Check for user API keys (if configured)
  const userApiKey = process.env.USER_API_KEY
  if (userApiKey && cleanToken === userApiKey) {
    return { id: 'user', role: 'user' }
  }

  return null
}

/**
 * Checks if user has admin role
 * @param user - Authenticated user object
 * @returns true if user is admin
 */
export function checkAdminRole(user: AuthUser | null): boolean {
  return user?.role === 'admin'
}

/**
 * Middleware to require authentication
 * @param handler - Route handler function
 * @returns Wrapped handler with authentication check
 */
export function requireAuth(
  handler: (request: NextRequest, user: AuthUser) => Promise<NextResponse>
) {
  return async (request: NextRequest) => {
    const token = request.headers.get('Authorization')

    if (!token) {
      return NextResponse.json(
        { success: false, error: 'Unauthorized - Missing token' },
        { status: 401 }
      )
    }

    // Validate token
    const user = await validateToken(token)
    if (!user) {
      return NextResponse.json(
        { success: false, error: 'Unauthorized - Invalid token' },
        { status: 401 }
      )
    }

    // Call handler with authenticated user
    return handler(request, user)
  }
}

/**
 * Middleware to require admin access
 * @param handler - Route handler function
 * @returns Wrapped handler with admin check
 */
export function requireAdmin(
  handler: (request: NextRequest, user: AuthUser) => Promise<NextResponse>
) {
  return async (request: NextRequest) => {
    const token = request.headers.get('Authorization')

    if (!token) {
      return NextResponse.json(
        { success: false, error: 'Unauthorized - Missing token' },
        { status: 401 }
      )
    }

    // Validate token
    const user = await validateToken(token)
    if (!user) {
      return NextResponse.json(
        { success: false, error: 'Unauthorized - Invalid token' },
        { status: 401 }
      )
    }

    // Check admin role
    if (!checkAdminRole(user)) {
      return NextResponse.json(
        { success: false, error: 'Forbidden - Admin access required' },
        { status: 403 }
      )
    }

    // Call handler with authenticated admin user
    return handler(request, user)
  }
}

/**
 * Optional authentication - adds user to request if token is valid
 * @param handler - Route handler function
 * @returns Wrapped handler with optional auth
 */
export function optionalAuth(
  handler: (
    request: NextRequest,
    user: AuthenticatedUser
  ) => Promise<NextResponse>
) {
  return async (request: NextRequest) => {
    const token = request.headers.get('Authorization')
    let user: AuthenticatedUser = null

    if (token) {
      user = await validateToken(token)
    }

    return handler(request, user)
  }
}

import { ObjectId } from 'mongodb'
import { connectDB } from '@/lib/mongodb'
import { MercadoLibreGrant } from './types'

const COLLECTION = 'mercado_libre_grants'

export async function getActiveGrant(): Promise<MercadoLibreGrant | null> {
  const db = await connectDB()
  const grant = await db
    .collection<MercadoLibreGrant>(COLLECTION)
    .find({ sellerId: { $exists: true } })
    .sort({ updatedAt: -1 })
    .limit(1)
    .next()

  return grant || null
}

export async function saveGrant(grant: Omit<MercadoLibreGrant, '_id' | 'createdAt' | 'updatedAt'>) {
  const db = await connectDB()
  const now = new Date()

  await db.collection<MercadoLibreGrant>(COLLECTION).updateOne(
    { sellerId: grant.sellerId },
    {
      $set: {
        accessToken: grant.accessToken,
        refreshToken: grant.refreshToken,
        scope: grant.scope,
        expiresAt: grant.expiresAt,
        userId: grant.userId,
        updatedAt: now
      },
      $setOnInsert: {
        createdAt: now,
        sellerId: grant.sellerId
      }
    },
    { upsert: true }
  )

}

export function isGrantExpired(grant: MercadoLibreGrant): boolean {
  return grant.expiresAt.getTime() <= Date.now()
}

export async function clearGrant(grantId: ObjectId) {
  const db = await connectDB()
  await db.collection<MercadoLibreGrant>(COLLECTION).deleteOne({ _id: grantId })
}

import { connectDB } from '@/lib/mongodb'
import crypto from 'crypto'
import { MercadoLibreAuthState } from './types'

const COLLECTION = 'mercado_libre_auth_state'
const EXPIRATION_MS = 15 * 60 * 1000 // 15 minutes

export async function createAuthState(
  options: { codeVerifier?: string; returnTo?: string } = {}
) {
  const state = crypto.randomBytes(32).toString('hex')
  const createdAt = new Date()
  const expiresAt = new Date(createdAt.getTime() + EXPIRATION_MS)

  const record: MercadoLibreAuthState = {
    state,
    codeVerifier: options.codeVerifier,
    returnTo: options.returnTo,
    createdAt,
    expiresAt,
  }

  const db = await connectDB()
  await db.collection<MercadoLibreAuthState>(COLLECTION).insertOne(record)

  return record
}

export async function consumeAuthState(
  state: string
): Promise<MercadoLibreAuthState | null> {
  if (!state) return null

  const db = await connectDB()
  const result = await db
    .collection<MercadoLibreAuthState>(COLLECTION)
    .findOneAndDelete({ state })

  // findOneAndDelete returns ModifyResult<T> with value property
  // Type assertion needed because MongoDB types may vary
  const authState =
    result && typeof result === 'object' && 'value' in result
      ? (result.value as MercadoLibreAuthState | null)
      : null
  if (!authState) {
    return null
  }

  if (authState.expiresAt.getTime() < Date.now()) {
    return null
  }

  return authState
}

import { connectDB } from '@/lib/mongodb'
import { MercadoLibreOrderRecord } from '@/models/Order'
import { callMercadoLibreAPI, getMercadoLibreConfig } from './client'
import { MercadoLibreOrder } from './types'

const COLLECTION = 'mercado_libre_orders'

export interface OrderSyncParams {
  limit?: number
  offset?: number
  status?: string
  dateFrom?: string
  dateTo?: string
}

export interface OrdersSummary {
  total: number
  pending: number
  paid: number
  delivered: number
  canceled: number
  totalRevenue: number
  currency: string
}

function normalizeOrder(order: MercadoLibreOrder): Omit<MercadoLibreOrderRecord, '_id' | 'createdAt'> {
  return {
    orderId: order.id,
    status: order.status,
    dateCreated: order.date_created,
    lastUpdated: order.date_last_updated || order.date_created,
    totalAmount: order.total_amount,
    currencyId: order.currency_id,
    buyer: {
      id: order.buyer?.id,
      nickname: order.buyer?.nickname,
      full_name: order.buyer?.first_name
        ? `${order.buyer?.first_name} ${order.buyer?.last_name || ''}`.trim()
        : order.buyer?.nickname,
      email: order.buyer?.email,
      phone: order.buyer?.phone?.number
    },
    payments: (order.payments || []).map((payment: any) => ({
      id: payment.id,
      status: payment.status,
      transaction_amount: payment.transaction_amount,
      method: payment.payment_method_id
    })),
    shipping: {
      status: order.shipping?.status,
      tracking_number: order.shipping?.tracking_number,
      mode: order.shipping?.shipping_mode
    },
    acknowledged: order.tags?.includes('paid') || false,
    readyToShip: order.shipping?.status === 'ready_to_ship',
    tags: order.tags || [],
    lastSync: new Date(),
    updatedAt: new Date()
  }
}

export async function syncSellerOrders(params: OrderSyncParams = {}) {
  const config = getMercadoLibreConfig()
  const query: Record<string, string> = {
    seller: config.sellerId,
    sort: 'date_desc',
    limit: String(params.limit ?? 20),
    offset: String(params.offset ?? 0)
  }

  if (params.status) {
    query['order.status'] = params.status
  }

  if (params.dateFrom) {
    query['order.date_created.from'] = params.dateFrom
  }

  if (params.dateTo) {
    query['order.date_created.to'] = params.dateTo
  }

  const response = await callMercadoLibreAPI<{
    results: MercadoLibreOrder[]
    paging: { total: number; limit: number; offset: number }
  }>({
    path: '/orders/search',
    query
  })

  const db = await connectDB()
  const collection = db.collection<MercadoLibreOrderRecord>(COLLECTION)
  const syncedOrders: MercadoLibreOrderRecord[] = []
  const now = new Date()

  for (const order of response.results || []) {
    const normalized = normalizeOrder(order)
    await collection.updateOne(
      { orderId: normalized.orderId },
      {
        $set: {
          ...normalized,
          updatedAt: now,
          lastSync: now
        },
        $setOnInsert: {
          createdAt: now,
          acknowledged: normalized.acknowledged
        }
      },
      { upsert: true }
    )
    syncedOrders.push({
      ...normalized,
      createdAt: now
    })
  }

  return {
    paging: response.paging,
    orders: syncedOrders
  }
}

export async function syncOrderById(orderId: number) {
  if (!orderId) {
    throw new Error('orderId es obligatorio')
  }

  const order = await callMercadoLibreAPI<MercadoLibreOrder>({
    path: `/orders/${orderId}`
  })

  const normalized = normalizeOrder(order)
  const db = await connectDB()
  const collection = db.collection<MercadoLibreOrderRecord>(COLLECTION)
  const now = new Date()

  await collection.updateOne(
    { orderId: normalized.orderId },
    {
      $set: {
        ...normalized,
        updatedAt: now,
        lastSync: now
      },
      $setOnInsert: {
        createdAt: now,
        acknowledged: normalized.acknowledged
      }
    },
    { upsert: true }
  )

  return collection.findOne({ orderId })
}

export async function getStoredOrders(limit: number = 20) {
  const db = await connectDB()
  const collection = db.collection<MercadoLibreOrderRecord>(COLLECTION)
  const orders = await collection.find({}).sort({ dateCreated: -1 }).limit(limit).toArray()
  return orders
}

export async function acknowledgeOrder(orderId: number) {
  const db = await connectDB()
  const collection = db.collection<MercadoLibreOrderRecord>(COLLECTION)
  await collection.updateOne(
    { orderId },
    {
      $set: {
        acknowledged: true,
        updatedAt: new Date()
      }
    }
  )
  return collection.findOne({ orderId })
}

export async function markOrderReadyToShip(orderId: number, trackingNumber?: string) {
  const db = await connectDB()
  const collection = db.collection<MercadoLibreOrderRecord>(COLLECTION)
  await collection.updateOne(
    { orderId },
    {
      $set: {
        readyToShip: true,
        'shipping.tracking_number': trackingNumber,
        updatedAt: new Date()
      }
    }
  )
  return collection.findOne({ orderId })
}

export async function getOrdersSummary(limit: number = 50): Promise<OrdersSummary> {
  const orders = await getStoredOrders(limit)
  const summary = orders.reduce(
    (acc, order) => {
      acc.total += 1
      acc.totalRevenue += order.totalAmount

      switch (order.status) {
        case 'paid':
          acc.paid += 1
          break
        case 'canceled':
          acc.canceled += 1
          break
        case 'delivered':
          acc.delivered += 1
          break
        default:
          acc.pending += 1
      }

      if (!acc.currency) {
        acc.currency = order.currencyId
      }

      return acc
    },
    {
      total: 0,
      pending: 0,
      paid: 0,
      delivered: 0,
      canceled: 0,
      totalRevenue: 0,
      currency: 'USD'
    } as OrdersSummary
  )

  return summary
}

import crypto from 'crypto'
import { ObjectId } from 'mongodb'
import { consumeAuthState, createAuthState } from './state-store'
import {
  clearGrant,
  getActiveGrant,
  isGrantExpired,
  saveGrant,
} from './token-store'
import {
  MercadoLibreApiRequestOptions,
  MercadoLibreConfig,
  MercadoLibreGrant,
  OAuthTokenResponse,
} from './types'

const TOKEN_ENDPOINT = '/oauth/token'
const AUTHORIZATION_ENDPOINT = '/authorization'
const DEFAULT_SCOPES = ['offline_access', 'read', 'write']

let cachedConfig: MercadoLibreConfig | null = null

function loadConfig(): MercadoLibreConfig {
  if (cachedConfig) {
    return cachedConfig
  }

  // Note: SecureConfig doesn't have getMercadoLibreConfig() method yet
  // Using environment variables directly for now
  // TODO: Add getMercadoLibreConfig() to SecureConfig if needed

  const requiredEnv = [
    'MERCADO_LIBRE_APP_ID',
    'MERCADO_LIBRE_CLIENT_SECRET',
    'MERCADO_LIBRE_REDIRECT_URI',
    'MERCADO_LIBRE_SELLER_ID',
  ] as const

  for (const envKey of requiredEnv) {
    if (!process.env[envKey]) {
      throw new Error(
        `Missing environment variable ${envKey} for Mercado Libre integration`
      )
    }
  }

  cachedConfig = {
    appId: process.env.MERCADO_LIBRE_APP_ID!,
    clientSecret: process.env.MERCADO_LIBRE_CLIENT_SECRET!,
    redirectUri: process.env.MERCADO_LIBRE_REDIRECT_URI!,
    sellerId: process.env.MERCADO_LIBRE_SELLER_ID!,
    webhookSecret: process.env.MERCADO_LIBRE_WEBHOOK_SECRET || '',
    authBaseUrl:
      process.env.MERCADO_LIBRE_AUTH_URL || 'https://auth.mercadolibre.com.ar',
    apiBaseUrl:
      process.env.MERCADO_LIBRE_API_URL || 'https://api.mercadolibre.com',
    scopes: (process.env.MERCADO_LIBRE_SCOPES || DEFAULT_SCOPES.join(' '))
      .split(/[ ,]+/)
      .filter(Boolean),
    pkceEnabled:
      (process.env.MERCADO_LIBRE_PKCE_ENABLED || 'true').toLowerCase() !==
      'false',
  }

  return cachedConfig
}

function base64URLEncode(buffer: Buffer) {
  return buffer
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '')
}

function sha256(buffer: Buffer) {
  return crypto.createHash('sha256').update(buffer).digest()
}

function generateCodeVerifier(): string {
  return base64URLEncode(crypto.randomBytes(32))
}

function calculateCodeChallenge(codeVerifier: string): string {
  return base64URLEncode(sha256(Buffer.from(codeVerifier)))
}

export async function startAuthorization(returnTo?: string) {
  const config = loadConfig()
  let codeVerifier: string | undefined
  let codeChallenge: string | undefined

  if (config.pkceEnabled) {
    codeVerifier = generateCodeVerifier()
    codeChallenge = calculateCodeChallenge(codeVerifier)
  }

  const authState = await createAuthState({ codeVerifier, returnTo })

  const params = new URLSearchParams({
    response_type: 'code',
    client_id: config.appId,
    redirect_uri: config.redirectUri,
    state: authState.state,
    scope: config.scopes.join(' '),
  })

  if (codeChallenge) {
    params.append('code_challenge', codeChallenge)
    params.append('code_challenge_method', 'S256')
  }

  const authorizationUrl = `${
    config.authBaseUrl
  }${AUTHORIZATION_ENDPOINT}?${params.toString()}`

  return {
    authorizationUrl,
    state: authState.state,
    expiresAt: authState.expiresAt,
  }
}

async function requestToken(body: Record<string, string>) {
  const config = loadConfig()
  const url = `${config.apiBaseUrl}${TOKEN_ENDPOINT}`
  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      Accept: 'application/json',
    },
    body: new URLSearchParams(body),
  })

  const payload = await response.json().catch(() => ({}))

  if (!response.ok) {
    const errorMessage =
      payload?.error_description ||
      payload?.message ||
      `Mercado Libre token error (${response.status})`
    const error = new Error(errorMessage)
    ;(error as any).details = payload
    throw error
  }

  return payload as OAuthTokenResponse
}

export async function handleAuthorizationCallback(code: string, state: string) {
  const authState = await consumeAuthState(state)

  if (!authState) {
    throw new Error('Estado de autorización inválido o expirado')
  }

  const config = loadConfig()
  const body: Record<string, string> = {
    grant_type: 'authorization_code',
    client_id: config.appId,
    client_secret: config.clientSecret,
    code,
    redirect_uri: config.redirectUri,
  }

  if (authState.codeVerifier) {
    body.code_verifier = authState.codeVerifier
  }

  const tokens = await requestToken(body)
  await persistGrantFromTokens(tokens, config.sellerId)

  return {
    redirectTo: authState.returnTo || '/dashboard?meli=connected',
    tokens,
  }
}

export async function refreshTokens(grant?: MercadoLibreGrant) {
  const activeGrant = grant || (await getActiveGrant())

  if (!activeGrant) {
    throw new Error('No existe un grant activo de Mercado Libre')
  }

  const config = loadConfig()

  const body: Record<string, string> = {
    grant_type: 'refresh_token',
    client_id: config.appId,
    client_secret: config.clientSecret,
    refresh_token: activeGrant.refreshToken,
  }

  const tokens = await requestToken(body)
  await persistGrantFromTokens(tokens, config.sellerId)

  return tokens
}

async function persistGrantFromTokens(
  tokens: OAuthTokenResponse,
  sellerId: string
) {
  const expiresAt = new Date(
    Date.now() + Math.max(tokens.expires_in - 60, 60) * 1000
  )

  await saveGrant({
    sellerId,
    userId: tokens.user_id,
    accessToken: tokens.access_token,
    refreshToken: tokens.refresh_token,
    scope: tokens.scope.split(' '),
    expiresAt,
  })
}

export async function getValidAccessToken(): Promise<string> {
  let grant = await getActiveGrant()

  if (!grant) {
    throw new Error(
      'Mercado Libre no está conectado. Completa el flujo de autorización.'
    )
  }

  if (isGrantExpired(grant)) {
    try {
      const tokens = await refreshTokens(grant)
      grant = {
        ...grant,
        accessToken: tokens.access_token,
        refreshToken: tokens.refresh_token,
        scope: tokens.scope.split(' '),
        expiresAt: new Date(
          Date.now() + Math.max(tokens.expires_in - 60, 60) * 1000
        ),
        updatedAt: new Date(),
      }
    } catch (error) {
      console.error('Error refreshing Mercado Libre token:', error)
      if ((error as any)?.details?.error === 'invalid_grant' && grant._id) {
        await clearGrant(new ObjectId(grant._id))
      }
      throw error
    }
  }

  return grant.accessToken
}

export async function callMercadoLibreAPI<T = any>(
  options: MercadoLibreApiRequestOptions
): Promise<T> {
  const config = loadConfig()
  const method = options.method || 'GET'
  let path = options.path || ''

  if (!path.startsWith('/')) {
    path = `/${path}`
  }

  const query = new URLSearchParams()
  if (options.query) {
    Object.entries(options.query).forEach(([key, value]) => {
      if (value !== undefined && value !== null) {
        query.append(key, String(value))
      }
    })
  }

  const url =
    query.size > 0
      ? `${config.apiBaseUrl}${path}?${query.toString()}`
      : `${config.apiBaseUrl}${path}`

  let token = await getValidAccessToken()

  const response = await fetch(url, {
    method,
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: 'application/json',
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    },
    body: options.body ? JSON.stringify(options.body) : undefined,
  })

  if (response.status === 401 && options.retryOnAuthError !== false) {
    await refreshTokens()
    token = await getValidAccessToken()

    return callMercadoLibreAPI<T>({
      ...options,
      retryOnAuthError: false,
    })
  }

  if (!response.ok) {
    const errorPayload = await response.json().catch(() => ({}))
    const errorMessage =
      errorPayload?.message ||
      errorPayload?.error ||
      `Mercado Libre API error (${response.status})`
    const error = new Error(errorMessage)
    ;(error as any).details = errorPayload
    throw error
  }

  return (await response.json()) as T
}

export function getMercadoLibreConfig(): MercadoLibreConfig {
  return loadConfig()
}

export async function getGrantStatus() {
  const grant = await getActiveGrant()

  if (!grant) {
    return {
      connected: false,
    }
  }

  return {
    connected: true,
    expiresAt: grant.expiresAt,
    scope: grant.scope,
    sellerId: grant.sellerId,
    userId: grant.userId,
  }
}

import crypto from 'crypto'
import { connectDB } from '@/lib/mongodb'
import { syncOrderById } from './orders'

const COLLECTION = 'mercado_libre_webhook_events'

export function verifyWebhookSignature(rawBody: string, signatureHeader: string | null): boolean {
  const secret = process.env.MERCADO_LIBRE_WEBHOOK_SECRET
  if (!secret) {
    console.warn('Mercado Libre webhook secret not configured. Skipping signature validation.')
    return true
  }

  if (!signatureHeader) {
    return false
  }

  const [algo, signature] = signatureHeader.split('=')
  if (!algo || !signature) {
    return false
  }

  const hmac = crypto.createHmac(algo as any, secret)
  hmac.update(rawBody, 'utf8')
  const expected = hmac.digest('hex')
  const received = Buffer.from(signature)
  const expectedBuffer = Buffer.from(expected)

  if (received.length !== expectedBuffer.length) {
    return false
  }

  return crypto.timingSafeEqual(received, expectedBuffer)
}

export async function storeWebhookEvent(event: any) {
  const db = await connectDB()
  const collection = db.collection(COLLECTION)
  await collection.insertOne({
    ...event,
    receivedAt: new Date()
  })
}

export async function getRecentWebhookEvents(limit: number = 25) {
  const db = await connectDB()
  const collection = db.collection(COLLECTION)
  return collection.find({}).sort({ receivedAt: -1 }).limit(limit).toArray()
}

export async function processWebhookEvent(event: any) {
  await storeWebhookEvent(event)

  try {
    if (event.topic === 'orders' && event.resource) {
      const orderId = parseInt(event.resource.split('/').pop() || '', 10)
      if (!isNaN(orderId)) {
        await syncOrderById(orderId)
      }
    }
  } catch (error) {
    console.error('Error processing Mercado Libre webhook event:', error)
  }
}

import { callMercadoLibreAPI, getMercadoLibreConfig } from './client'
import { MercadoLibreListing } from './types'

export interface ListingQueryParams {
  status?: string
  limit?: number
  offset?: number
}

export interface ListingSyncResult {
  listings: MercadoLibreListing[]
  paging: {
    total: number
    limit: number
    offset: number
  }
}

const MAX_ITEMS_PER_REQUEST = 20

function chunk<T>(items: T[], size: number): T[][] {
  const chunks: T[][] = []
  for (let i = 0; i < items.length; i += size) {
    chunks.push(items.slice(i, i + size))
  }
  return chunks
}

export async function fetchSellerListings(params: ListingQueryParams = {}): Promise<ListingSyncResult> {
  const config = getMercadoLibreConfig()
  const query = {
    seller_id: config.sellerId,
    limit: String(params.limit ?? 20),
    offset: String(params.offset ?? 0),
    ...(params.status ? { status: params.status } : {})
  }

  const search = await callMercadoLibreAPI<{
    results: string[]
    paging: { total: number; limit: number; offset: number }
  }>({
    path: `/users/${config.sellerId}/items/search`,
    query
  })

  const listings: MercadoLibreListing[] = []
  const ids = search.results || []

  if (ids.length) {
    const idChunks = chunk(ids, MAX_ITEMS_PER_REQUEST)
    for (const idChunk of idChunks) {
      const detailResponse = await callMercadoLibreAPI<
        Array<{
          code: number
          body: MercadoLibreListing
        }>
      >({
        path: '/items',
        query: { ids: idChunk.join(',') }
      })

      detailResponse
        .filter((entry) => entry.code === 200 && !!entry.body)
        .forEach((entry) => listings.push(entry.body))
    }
  }

  return {
    listings,
    paging: search.paging || {
      total: listings.length,
      limit: params.limit ?? listings.length,
      offset: params.offset ?? 0
    }
  }
}

export async function getListing(listingId: string): Promise<MercadoLibreListing> {
  if (!listingId) {
    throw new Error('listingId es requerido')
  }

  return callMercadoLibreAPI<MercadoLibreListing>({
    path: `/items/${listingId}`
  })
}

export async function createListing(payload: Partial<MercadoLibreListing>) {
  if (!payload.title || !payload.price || !payload.currency_id || !payload.available_quantity) {
    throw new Error('Campos mínimos requeridos: title, price, currency_id, available_quantity')
  }

  return callMercadoLibreAPI<MercadoLibreListing>({
    method: 'POST',
    path: '/items',
    body: payload
  })
}

export async function updateListing(listingId: string, payload: Partial<MercadoLibreListing>) {
  if (!listingId) {
    throw new Error('listingId es requerido')
  }

  return callMercadoLibreAPI<MercadoLibreListing>({
    method: 'PUT',
    path: `/items/${listingId}`,
    body: payload
  })
}

export async function changeListingStatus(
  listingId: string,
  status: 'active' | 'paused' | 'closed'
) {
  if (!listingId) {
    throw new Error('listingId es requerido')
  }

  return callMercadoLibreAPI<MercadoLibreListing>({
    method: 'PUT',
    path: `/items/${listingId}`,
    body: { status }
  })
}

