    {
      "parameters": {
        "functionCode": "// Format response message for WhatsApp\nconst data = $json;\nconst originalData = $('Extract Message Data').item.json;\n\nlet responseText = data.mensaje || 'Lo siento, no pude procesar tu mensaje.';\n\n// Add formatting based on type\nif (data.tipo === 'cotizacion' && data.cotizacion) {\n  const cotizacion = data.cotizacion;\n  responseText = `🏗️ *COTIZACIÓN BMC*\\n\\n`;\n  responseText += `📋 *Código:* ${cotizacion.codigo || 'N/A'}\\n`;\n  responseText += `🏠 *Producto:* ${cotizacion.producto || 'N/A'}\\n`;\n  if (cotizacion.descripcion) {\n    responseText += `📐 *Descripción:* ${cotizacion.descripcion}\\n`;\n  }\n  if (cotizacion.total) {\n    responseText += `💰 *Precio Total:* $${cotizacion.total.toLocaleString('es-UY')}\\n`;\n  }\n  if (cotizacion.precio_m2) {\n    responseText += `📊 *Precio por m²:* $${cotizacion.precio_m2.toLocaleString('es-UY')}\\n\\n`;\n  }\n  \n  if (cotizacion.recomendaciones && cotizacion.recomendaciones.length > 0) {\n    responseText += `💡 *Recomendaciones:*\\n`;\n    cotizacion.recomendaciones.forEach(rec => {\n      responseText += `• ${rec}\\n`;\n    });\n    responseText += `\\n`;\n  }\n  \n  if (data.proximos_pasos && data.proximos_pasos.length > 0) {\n    responseText += `📞 *Próximos pasos:*\\n`;\n    data.proximos_pasos.forEach(paso => {\n      responseText += `• ${paso}\\n`;\n    });\n  }\n}\n\nreturn {\n  json: {\n    to: originalData.telefono,\n    message: responseText,\n    type: 'text',\n    sessionId: originalData.sesionId,\n    messageId: originalData.messageId\n  }\n};"
      },
